insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('rodpump', 'advanced', 'module', 'm01-the-envelope-and-the-subsample', 1, 'While predictCard marches ODUMA-4 at the shipped defaults, what does the tension envelope hold?', '["The load at each of the 186 points the card keeps, which is why prlPeakLb and prlMinLb can be read straight off it.", "A running maximum and a running minimum of the tension at each of the 120 interior nodes, updated at every one of the 6110 steps in the cycle.", "The maximum tension only, because a march still settling toward a repeating stroke cannot be trusted to report a minimum before it converges in time.", "One load and one position for every node, so that the card area can be integrated over the closed loop the envelope traces."]'::jsonb, 1, 'It is two numbers a node with no time index attached, accumulated over all 6110 marched steps at all 120 interior nodes, and nothing is thrown away from it.'),
  ('rodpump', 'advanced', 'module', 'm01-the-envelope-and-the-subsample', 2, 'Why can a card area never be computed from the tension envelope?', '["The envelope is accumulated only while the polished rod is rising, so half of the loop it would need is never recorded at all.", "A shoelace integral needs the 186 point card, and the envelope is stored on the 120 node grid, which is far too coarse to close a loop.", "The card area of 750654.615621 in-lb is formed from prlPeakLb and prlMinLb, and the envelope contains neither of those two fields.", "It carries no position and no time against its two loads, so there is no closed loop of load against position to integrate."]'::jsonb, 3, 'The envelope holds a maximum and a minimum load per node and nothing else, which is what a fatigue check needs and what an area cannot be got from.'),
  ('rodpump', 'advanced', 'module', 'm01-the-envelope-and-the-subsample', 3, 'cardSamples defaults to 180. How much of the ODUMA-4 march survives into the surface card the two reported loads are read off?', '["186 points of the 6110 marched steps, a stride of 33, which is 3.044190 percent.", "180 points exactly, because the decimation resamples onto the requested count rather than taking a stride through the recorded steps.", "All 6110 steps, since cardSamples sets only how many points are drawn on the plot and not how many the two maxima are taken over.", "1019 points, the count the card keeps once the stride has fallen to 6 and the march has stopped discarding anything."]'::jsonb, 0, 'A stride of 33 is taken through the recorded steps, so 186 survive out of 6110, and prlPeakLb and prlMinLb are the extremes of those.'),
  ('rodpump', 'advanced', 'module', 'm01-the-envelope-and-the-subsample', 4, 'On ODUMA-4 at the shipped defaults the reported minimum polished rod load is 2625.472706 lb. What did the march itself find?', '["2625.472706 lb as well, because prlMinLb is the minimum over every marched step and only the plotted card is ever decimated.", "2331.994757 lb, the minimum the tension envelope accumulated at the shallowest node, which is the same quantity read without decimation.", "2104.494479 lb, so the reported value is 520.978227 lb high, a reported over real ratio of 1.247555046.", "2513.106558 lb, the value at a cardSamples of 240, which is what the design forwards once the default proves too coarse for the transfer."]'::jsonb, 2, 'The reported minimum is the smallest of 186 chosen points and the march found 2104.494479 lb, 24.755505 percent lower.'),
  ('rodpump', 'advanced', 'module', 'm01-the-envelope-and-the-subsample', 5, 'The same default card reports the peak 1.896103 percent low and the minimum 24.755505 percent high. Why is the minimum so much worse?', '["The minimum is the smaller number, so one absolute sampling error of 520.978227 lb has to come back as the larger of the two percentages.", "The minimum sits in the narrow load transfer where the card is changing fastest, so a coarse sample is least likely to land on it.", "The peak is taken from the tension envelope while the minimum is taken from the card, so only one of the two is decimated at all.", "The minimum is read at the pump node and the peak at the polished rod, and the pump node travels furthest between two recorded steps."]'::jsonb, 1, 'Both come off the same 186 point subsample; the peak is 377.772986 lb low and the minimum 520.978227 lb high because the card is steepest where the minimum falls.'),
  ('rodpump', 'advanced', 'module', 'm01-the-envelope-and-the-subsample', 6, 'Which reported quantity does the decimation leave untouched, and why?', '["The plunger stroke, 98.526653100 in at the default and at stride 1, because it is a peak to trough of the pump node taken over every marched step.", "The card area, since a shoelace integral over a closed loop is insensitive to how many points the loop happens to be drawn with.", "The load range, because the peak and the minimum are pulled in by the same stride and the narrowing cancels between the two of them.", "The polished rod horsepower, which is fixed by the speed and the surface stroke and never reads the card the subsample produced."]'::jsonb, 0, 'The stroke reads 98.526653100 in either way, a difference of 0.000e+0 in, so everything proportional to it including the swept and produced rates survives.'),
  ('rodpump', 'advanced', 'module', 'm01-the-envelope-and-the-subsample', 7, 'A 60 point card on ODUMA-4 reports a peak of 19841.734514 lb and a 90 point card reports 19452.336562 lb. What does that ordering show?', '["The 60 point card is nearer the truth, so the sampling error falls as the count is reduced and the shipped default of 180 is already too fine.", "The march changed between the two runs, since cardSamples sets the recorded step count and through it the time step the march is able to use.", "The peak has converged by 60 points and the remaining difference is round-off in the shoelace sum that follows it.", "Neither column is monotone in cardSamples, because a coarse stride can happen to land near an extreme and then miss it at the next stride."]'::jsonb, 3, 'The march is bit for bit identical at every row, and marching every step gives 19923.650769 lb, which both of those rows read low.'),
  ('rodpump', 'advanced', 'module', 'm01-the-envelope-and-the-subsample', 8, 'One call to predictCard on ODUMA-4 returns two answers for the peak polished rod load. Name them and the size of the gap.', '["prlPeakLb reports 19545.877783339 lb and the fully sampled card gives 19923.650769100 lb, and the envelope route is a third name for that same fully sampled value.", "prlPeakLb reports 19545.877783339 lb against an envelope maximum of 19800.044639044 lb at the shallowest node, which is the second answer with the buoyed rod above that node left out.", "prlPeakLb reports 19545.877783339 lb and the envelope implies 19851.465785541 lb, a gap of 305.588002202 lb.", "There is only one peak in the object, since the tension envelope stores its maximum at the pump node, which is a load on the plunger and not a polished rod load."]'::jsonb, 2, 'The gap is 305.588002202 lb, 1.563440 percent, and no field in the return says the two were built from different sets of steps.'),
  ('rodpump', 'advanced', 'module', 'm01-the-envelope-and-the-subsample', 9, 'Why is 51.421146497 lb added to the envelope maximum before it can be called a peak polished rod load?', '["The shallowest envelope sample sits at 20.000000000 ft rather than at the surface, so the buoyed weight of the rod above it has to be put back.", "It is the structural unbalance of the beam, which the polished rod carries on top of the tension the envelope recorded at the first node.", "It restores the buoyancy Archimedes took off the top section, because the envelope stores tensions in air while the surface card stores them in fluid.", "It closes the 305.588002202 lb gap between the two routes, which is the whole reason the addition is made."]'::jsonb, 0, 'Node spacing on this grid is 40.000000000 ft, so the first sample is half a spacing down and 51.421146497 lb of buoyed rod stands above it.'),
  ('rodpump', 'advanced', 'module', 'm01-the-envelope-and-the-subsample', 10, 'In one runRodPumpDesign return, which peak load does the modified Goodman check read and which does rating.structuralPct read?', '["Both read prlPeakLb, and the tension envelope is kept only for the section stresses the diagnostic solver is handed later.", "The Goodman line reads the envelope and structuralPct reads prlPeakLb, so the check deciding whether the unit is big enough is fed the smaller number.", "The Goodman line reads prlPeakLb and structuralPct reads the envelope, which is what makes the structural check the conservative one of the two.", "Both read the envelope, since a rating percentage taken from a subsample would be indefensible and the module avoids it."]'::jsonb, 1, 'sectionStresses and the Goodman line read the envelope; structuralPct and the structuralOverload warning read the 186 point subsample.'),
  ('rodpump', 'advanced', 'module', 'm01-the-envelope-and-the-subsample', 11, 'Against a structural capacity of 19800 lb the design reports structuralPct as 98.716554461 percent. What would the marched peak have given?', '["98.716554461 percent as well, because structuralPct is formed from the envelope and the envelope is never decimated.", "82.873308396 percent, the worst section loading.", "100.624498834 percent, so structuralOverload fires on one route and stays silent on the other.", "106.687716837 percent, the strokePct the design returns and the only percentage anywhere in the object that passes 100."]'::jsonb, 2, 'The teaching capacity was chosen to sit between the subsampled peak and the marched peak, so one design passes on one route and overloads on the other.'),
  ('rodpump', 'advanced', 'module', 'm01-the-envelope-and-the-subsample', 12, 'Balancing ODUMA-4 uses the only surface card predictCard hands out. What does that do to the peak gearbox torque?', '["Nothing, because balanceUnit accumulates its own torque envelope over every marched step exactly as the tension envelope is accumulated.", "It reads the torque 2.467917 percent high, since a coarse card exaggerates the two peaks the bisection is driven to equalise.", "It moves the counterbalance moment by 188.587503 lb, which is the whole of the effect decimation has on a balance.", "It reads 450016.096192 in-lb off the 186 point card against 461403.140996 in-lb off the full march, which is 2.467917 percent low."]'::jsonb, 3, 'The gearbox check is the third reader of the subsample, and torquePct comes out 140.630030060 percent from the default card against 144.188481561 percent from the full march.'),
  ('rodpump', 'advanced', 'module', 'm01-the-envelope-and-the-subsample', 13, 'A studio user suspects the reported loads are subsampled. What can they do about it through runRodPumpDesign?', '["Nothing, because it forwards neither cardSamples nor nodes to the card solver it calls.", "Raise cardSamples to 7000 and read the marched pair back.", "Read the tension envelope the same return already carries and take its shallowest node as the peak instead of prlPeakLb.", "Compare prlPeakLb against the structuralOverload warning, which fires whenever the two samplings of one march disagree by more than a percent."]'::jsonb, 0, 'predictCard accepts cardSamples 180, nodes 120, maxCycles 20 and tol 0.0001, and the design function passes none of them, so the card has to be solved separately.'),
  ('rodpump', 'advanced', 'module', 'm01-the-envelope-and-the-subsample', 14, 'At 10.0 spm on ODUMA-4 the reported minimum load is 2625.472706 lb against a marched 2104.494479 lb. What happens to that comparison at 12.0 spm?', '["The ratio simply grows to 3.380387, which is the largest overstatement anywhere in the speed sweep and still leaves the sign intact.", "The reported minimum reads 45.754029 lb where the march found -466.104183 lb, so the two disagree about whether the load goes negative at all.", "Both readings go negative together, since a card sampled at any stride still crosses zero wherever the underlying march crosses it.", "The reported minimum becomes the more negative of the two, because a coarse sample lands inside the load transfer more often at higher speed."]'::jsonb, 1, 'A negative minimum says the rods are in compression, and on that row and again at 12.5 spm the reported number delivers the opposite verdict.'),
  ('rodpump', 'advanced', 'module', 'm01-the-envelope-and-the-subsample', 15, 'Two separate effects sit at the top of the ODUMA-4 string: a half node of rod and a decimated card. Why must they not be conflated?', '["They are one effect counted twice, since the buoyed rod above the shallowest node is exactly what the decimation removed from the reported peak.", "The half node is the larger of the two on this well, so a reader who repairs the sampling is left with most of the disagreement still in place.", "Neither matters once the envelope route is taken, because 19851.465785541 lb sits within round-off of the fully sampled 19923.650769100 lb.", "The half node is a discretisation choice worth 0.259029 percent while the disagreement between the two routes is 1.563440 percent, and confusing them flattens the larger problem into the smaller."]'::jsonb, 3, 'The envelope route sits -72.184983559 lb from the marched peak and prlPeakLb sits -377.772985761 lb from it, so the sampling choice is the large one.'),
  ('rodpump', 'advanced', 'module', 'm02-convergence', 1, 'The march is explicit, so what happens to the time step when the node count is doubled?', '["It is unaffected, because the step is set by the pumping speed and the number of cycles rather than by the grid the wave is marched on.", "It doubles with the grid, since a finer mesh resolves the wave better and lets the march take longer steps through it.", "It has to shrink with the node spacing to hold the Courant condition, so the steps in a cycle roughly double as well.", "It is chosen by the tolerance of 0.0001, so a finer grid changes only how many cycles are needed before the card repeats."]'::jsonb, 2, 'On ODUMA-4 the marched steps run 3055, 6110, 12219, 24437, 48874 and 97747 across node counts of 60 to 1920, so the cost of a run rises as the square.'),
  ('rodpump', 'advanced', 'module', 'm02-convergence', 2, 'Across node counts of 60 to 1920 on ODUMA-4, which quantity settles and which do not?', '["The plunger stroke moves 0.044644 percent while the peak load moves 1.683064 percent and the minimum 10.864298 percent of the smallest.", "All three settle together, since the same march produced them and a converged march converges in every field it returns.", "The two loads settle and the plunger stroke does not, because a position is accumulated over a whole cycle and errors add along it.", "The plunger stroke moves 0.043975327 in, which is the largest of the three movements once every column is put into the same units."]'::jsonb, 0, 'The stroke moves 0.043975327 in over those six grids while the peak moves 325.459098 lb and the minimum 264.331784 lb.'),
  ('rodpump', 'advanced', 'module', 'm02-convergence', 3, 'Why is the plunger stroke the honest half of a node sweep and the load pair the fragile half?', '["The stroke is computed by a closed form that never enters the march, so it carries no grid error of any kind into the returned object.", "The stroke is a peak to trough of a position over a cycle, which is an integral of the wave, while the load extremes are point values of a spatial derivative at whichever instant was worst.", "The loads are read off the decimated card and the stroke is not, so the whole of the difference between them is the card subsample.", "The stroke is reported to fewer figures, so its movement across the grid falls below the precision the design chose to print."]'::jsonb, 1, 'A derivative sampled on a coarser mesh is the first thing to move, which is why everything proportional to the 0.044644 percent stroke survives the grid and the loads do not.'),
  ('rodpump', 'advanced', 'module', 'm02-convergence', 4, 'The ODUMA-4 peak load reads 19662.751698 lb at 240 nodes, 19551.233793 lb at 480 and 19520.004895 lb at 960. What does that sequence rule out?', '["Using the 120 node default at all, since every finer grid agrees with itself and only the shipped one is out of line with them.", "Any reading of the peak load, because a column that is not monotone in the grid cannot be a solution of the wave equation at all.", "The Courant condition, because a time step that followed the node spacing would give a peak that fell steadily as the mesh was refined.", "Refining the grid until the answer stops changing, because the answer changes back."]'::jsonb, 3, 'The peak rises through 240 nodes, falls at 480 and 960, then rises again to 19590.579526 lb at 1920, so there is no monotone limit to stop at.'),
  ('rodpump', 'advanced', 'module', 'm02-convergence', 5, 'Run ODUMA-4 at 11 spm with a damping ratio of 0.05 and sweep the same six grids. What happens to the spreads?', '["They collapse, because a lower damping ratio lets the march settle sooner and every grid then reaches the same repeating stroke.", "Only the loads spread further, since the plunger stroke is an integral of the wave and stays inside its 0.044644 percent whatever the operating point is.", "The plunger stroke spreads 1.908577 percent, the peak load 11.523296 percent and the minimum 66.702711 percent of the smallest.", "The spreads are unchanged, because moving the speed and the damping moves the well and not the grid the answer is computed on."]'::jsonb, 2, 'The worst section loading spreads 6.686252312 percentage points there, and every one of those six rows still sits above 100 percent, so the verdict holds while the number does not.'),
  ('rodpump', 'advanced', 'module', 'm02-convergence', 6, 'On those same low damping rows the notPeriodic flag reads false, false, false, true, false, true down the node counts. What does that establish?', '["The march is diverging as the grid is refined, so the two rows that raise it are the only trustworthy ones in the sweep.", "The flag is not monotone in resolution, so a middling grid can raise it while both a coarser and a finer one settle.", "The flag tracks the damping ratio rather than the grid, which is why raising the damping is the advice the message gives.", "The tolerance of 0.0001 is too tight for a fine grid, so the flag appears whenever the node count passes 240 and cannot be met."]'::jsonb, 1, 'Those two rows marched all 20 cycles while 240 nodes settled in 5 and 960 nodes in 16, and nothing about the well changed between any of them.'),
  ('rodpump', 'advanced', 'module', 'm02-convergence', 7, 'The notPeriodic message asks the reader to raise the damping or check the inputs. Why is that advice unusable here?', '["Nothing about the well changed between the grids that settled and the one that did not, and the node count is a parameter runRodPumpDesign does not expose.", "The message names no section, so a reader cannot tell which part of the taper failed to settle into a repeating stroke.", "The damping ratio of 0.05 is already below the 0.05 to 0.15 band the engine names, so raising it would put the run outside the range it accepts.", "The design refuses the run outright when the flag is raised, so there is no answer left to act on by the time the advice is read."]'::jsonb, 0, 'maxCycles defaults to 20 and neither it nor the node count is forwarded, so a caller who sees the warning has nothing to turn.'),
  ('rodpump', 'advanced', 'module', 'm02-convergence', 8, 'A run comes back with converged true on the shipped 120 node grid. What has the engine asserted?', '["That the loads would survive a finer mesh, since a march that repeats on one grid repeats on every finer one by the same argument.", "That the card sampling and the node count were both adequate, because the convergence test is applied to the returned card and not to the march.", "That the plunger stroke and both load extremes are converged to the last figure printed, which is why no grid error is attached to them.", "That the march settled into a repeating stroke within the tolerance on the grid it was given, and nothing about whether that grid was fine enough."]'::jsonb, 3, 'It is a convergence in time on one grid, and the return carries no measure of grid error at all.'),
  ('rodpump', 'advanced', 'module', 'm02-convergence', 9, 'A node study cannot be run through runRodPumpDesign, so the loading has to be recomputed standalone. What licenses that route?', '["The oracle holds the two independent routes to 3 percent on the minimum load, which is wider than any movement a node sweep produces.", "At the shipped defaults the design returns 82.873308395930 percent and the standalone recomputation returns 82.873308395930 percent, strictly equal.", "sectionStresses and modifiedGoodman are pure functions of the card and of the string beneath it, so any route that calls the two of them in either order has to return the same figure.", "The standalone route uses the tension envelope while the design uses the decimated card, and the envelope is the better of the two."]'::jsonb, 1, 'Strict equality at the shipped grid is the check on the route, and without it the node sweep would be measuring the recomputation instead of the grid.'),
  ('rodpump', 'advanced', 'module', 'm02-convergence', 10, 'Sweeping the speed on ODUMA-4 the worst section loading reads 89.649462, 88.179235 and 97.785820 percent at 10.4, 10.6 and 10.8 spm. What is the dip worth?', '["The whole climb from 88.179235 percent to the 97.785820 percent of the row that follows it, which is the size a design decision would be built on.", "Nothing, because the 10.6 spm row failed to converge and was excluded from the sweep before the comparison was made.", "1.470226 percentage points below the row before it, which is what makes it look like an operating point worth taking.", "0.936333 percentage points, which is the depth of the dip once the node spread at that speed is subtracted from it."]'::jsonb, 2, 'The dip is 1.470226 percentage points deep and every row of that sweep reports converged, so nothing in the return marks it as suspect.'),
  ('rodpump', 'advanced', 'module', 'm02-convergence', 11, 'Hold ODUMA-4 at one speed and move only the node count. How far does the worst section loading travel?', '["4.283675 percentage points at 10.4 spm and 6.553883 percentage points at 10.8 spm, over six node counts from 60 to 1920.", "It does not travel at all, since the loading is computed from the section stresses and those come out of a grid independent envelope.", "1.577289838 percentage points at any speed, which is the spread the shipped operating point produces and the figure a reader should carry.", "2.104178 percentage points at every speed in the sweep, because the node spread is a property of the string rather than of the operating point."]'::jsonb, 0, 'The dip is 0.343216 times the spread at the row before it and 0.224329 times the spread at the row after it, so a parameter with no physical content moves the number further than the speed change did.'),
  ('rodpump', 'advanced', 'module', 'm02-convergence', 12, 'What does the comparison between the speed sweep and the node sweep not claim?', '["That the dip is real in the sense that the solver printed it, which is a claim the comparison denies outright.", "That the node spread has to be measured at the very speed being read, because it comes to 0.936333 percentage points at one speed in that sweep and 6.553883 percentage points at another.", "That the plunger stroke survives the grid, which the same six node counts settle at 0.044644 percent.", "That the coarse answer is wrong and the fine one right, since both sweeps compute the same quantity and one of them varies a parameter with no physical content."]'::jsonb, 3, 'The refusal rests on the size of the movement rather than on any grid being authoritative, and the dip is 0.224329 times the spread at 10.8 spm.'),
  ('rodpump', 'advanced', 'module', 'm02-convergence', 13, 'The loading reads 78.955358 percent at 9.0 spm and 99.637760 percent at 11.0 spm. What does the sweep resolve?', '["Nothing at all, since every row sits inside a grid noise no pair of rows can clear.", "The optimum speed, because the two ends of the range bracket the dip and a bracketed dip is a minimum of the curve between them.", "The direction across its range, because that movement is far larger than any node spread on this well.", "The ordering of adjacent rows, since the floors of 2.104178 and 4.283675 percentage points apply only to the loading and not to the speed."]'::jsonb, 2, 'A sweep can resolve a trend it cannot use to rank neighbours, and the floor at 10.4 spm alone is 4.283675 percentage points.'),
  ('rodpump', 'advanced', 'module', 'm02-convergence', 14, 'The reported minimum load reads -359.286455 lb at 11.0 spm, 1464.558895 lb at 11.2, 855.932624 lb at 11.4 and -1115.467356 lb at 11.6. Why can the sweep not locate where the rods go into compression?', '["The sign changes twice in four contiguous rows, and the column it changes in is the decimated one, which at 12.0 spm reads 45.754029 lb where the march found -466.104183 lb.", "Every one of those rows failed the periodicity test, so the loads are indicative and the engine says as much in its message.", "Compression is a property of the deepest node in the taper and the reported minimum is a polished rod load read at the surface, so the sweep is being asked about the wrong end of the string.", "The minimum load is not returned above 11.0 spm, because the design refuses any speed that approaches the string fundamental."]'::jsonb, 0, 'The sweep is being asked to find a sign change in a column sampled well enough to lose the sign, and every one of those rows reports converged.'),
  ('rodpump', 'advanced', 'module', 'm02-convergence', 15, 'What does a sweep refuse to tell a reader about its own rows?', '["Which row converged, since the flag is raised on the card rather than on the march and cannot be read row by row.", "How far apart two rows have to be before the difference is real, because nothing in the return prices the grid spread.", "The service factor behind each loading, which is the only quantity that would let two rows of a speed sweep be compared at all.", "Whether the speed being swept is below the string fundamental, which the engine checks once and never repeats down the rows."]'::jsonb, 1, 'The only route to the floor is to hold the well fixed and move a parameter with no physical content, which gives 0.936333 percentage points at 10.6 spm and 6.553883 at 10.8 spm.'),
  ('rodpump', 'advanced', 'module', 'm03-the-counterbalance', 1, 'The counterweight term in the net gearbox torque is a sine. What is it anchored to, and why to that?', '["The crank angle a maker calls zero, so that a unit ordered out of a catalogue can be balanced from its published crank position alone.", "The crank angle at the bottom of the polished rod stroke, 359.000000000 deg on this linkage, which makes the weight rise while the rods are being lifted.", "The crank angle at which the rod torque is largest, 60.0 deg on this linkage, so that the two terms of the net torque reach their peaks together.", "The top of the polished rod stroke, which is where the torque factor changes sign and the beam begins to carry the fluid load on the rods."]'::jsonb, 1, 'It is sample index 359 of 360, so the sign is right by construction rather than by convention, and the balanced moment comes out 609641.972281 in-lb.'),
  ('rodpump', 'advanced', 'module', 'm03-the-counterbalance', 2, 'With no counterweight at all the ODUMA-4 gearbox sees 950041.862527 in-lb. What does balancing the unit do to that?', '["It brings the peak to 646133.044285 in-lb, the downstroke peak of the unweighted unit, which is the largest torque left once the upstroke has been carried by the weight.", "It leaves the peak where it is and moves only the crank angle at which it falls, because a counterweight redistributes torque through the revolution rather than removing any of it.", "It brings the peak to 609641.972281 in-lb, the counterweight moment itself, because the gearbox has to lift that weight back over the top on the downstroke.", "It brings the peak to 450016.096192 in-lb, a reduction of 52.631972 percent."]'::jsonb, 3, 'The larger of the two peaks is what the gearbox sees, and the balance equalises them at 450016.096192 in-lb, 52.631972 percent below the unweighted 950041.862527 in-lb.'),
  ('rodpump', 'advanced', 'module', 'm03-the-counterbalance', 3, 'At 90.0 deg of crank on balanced ODUMA-4 the counterweight term reads 609549.120856 in-lb against a moment of 609641.972281 in-lb. Why the near miss?', '["A quarter turn from the anchor is where the sine peaks, and the anchor is sample 359 of 360, so 90.0 deg sits one sample past the maximum.", "The counterweight moment is stated at the crank while the term in the net torque is stated at the polished rod, and the front arm of 106.6667 in separates the two.", "The bisection closes on a tolerance rather than on an exact equality, so the moment it returns falls short of the term it produces by the width of the last bracket.", "The rod torque of -600005.000534 in-lb is taken off the moment before it enters the net torque, and the difference is what the table prints."]'::jsonb, 0, 'The sine peaks at sample 89, a quarter turn from the bottom of the stroke, and at 270.0 deg the same term reads -609549.120856 in-lb.'),
  ('rodpump', 'advanced', 'module', 'm03-the-counterbalance', 4, 'Between 240.0 and 255.0 deg of crank the net torque on balanced ODUMA-4 swings to -434503.712662 in-lb. What put that step into it?', '["The torque factor changes sign inside that interval, so the rod term reverses and the counterweight term is left carrying the whole of the net.", "The counterweight sine passes its negative peak of -609549.120856 in-lb there, so the swing belongs to the weight and not to the card at all.", "The polished rod load falls from 11077.067719 lb to 2835.207157 lb across a valve transfer, so the rod torque collapses while the counterweight term moves far less.", "The march had not settled over that part of the cycle, so the load the balance read on those two samples is the one notPeriodic was raised on."]'::jsonb, 2, 'Rod torque goes from 552620.335836 in-lb to 157029.287601 in-lb between those two angles, and the balance, being a condition on two peaks, never sees the swing between them.'),
  ('rodpump', 'advanced', 'module', 'm03-the-counterbalance', 5, 'Set the ODUMA-4 counterweight moment at 1.1000 of the balanced value. What does the gearbox then see?', '["400077.149404 in-lb, the upstroke peak, since the upstroke is the loaded half of the cycle and the downstroke peak is carried by the falling weight itself.", "509648.079442 in-lb, the downstroke peak, because the gearbox carries the larger of the two peaks and overweighting raises that one.", "450016.096192 in-lb, unchanged, because the bisection re-solves the balance whenever the moment it is handed sits off the crossing.", "The average of the two peaks, which is what a gearbox rated on a duty cycle actually carries through a revolution rather than either extreme of it."]'::jsonb, 1, 'At 1.1000 the two peaks read 400077.149404 in-lb and 509648.079442 in-lb, and at 2.0000 the larger is 1046335.928686 in-lb, so overweighting costs as surely as underweighting.'),
  ('rodpump', 'advanced', 'module', 'm03-the-counterbalance', 6, 'Dividing the ODUMA-4 counterweight moment of 609641.972281 in-lb by the front arm gives 5715.391704 lb. What is wrong with that number?', '["The moment acts through the crank and the torque factor rather than through the beam arm, so the division understates the effect by a factor of 2.363578.", "It is the right arithmetic on the wrong moment, since the front arm divides the net torque at the bottom of the stroke and not the counterweight moment.", "It leaves out the structural unbalance the beam puts on the polished rod, which is the whole of the gap between it and the effect of 13508.771698 lb.", "Nothing is wrong with it as a load, but it is quoted at the equalizer bearing rather than at the polished rod, which is where a crew hangs its gauge."]'::jsonb, 0, 'The counterbalance effect is 13508.771698 lb, read where the torque factor is 45.129341579 in, and a crew set to 5715.391704 lb would run a unit below its own rod weight of 9466.342675 lb.'),
  ('rodpump', 'advanced', 'module', 'm03-the-counterbalance', 7, 'The ODUMA-4 counterbalance effect is 13508.771698 lb and the buoyed rod weight is 9466.342675 lb. What is the field check that pair invites?', '["The effect should have come back equal to the buoyed rod weight, and the 4042.429023 lb above it is the structural unbalance the beam adds at the polished rod.", "The effect should have come back at the peak polished rod load less the rod weight, so that the fluid is lifted by the beam and the rods by the weight.", "The effect should sit below the rod weight by the fluid load, because the counterweight has only to carry what the rods weigh while they are falling.", "The effect sits 4042.429023 lb above the rod weight, which is roughly the rod weight plus half the fluid load of 2345.149829 lb."]'::jsonb, 3, 'The engine lands on the rule a crew carries without being told to: 13508.771698 lb against 9466.342675 lb of buoyed rod is 4042.429023 lb, near half the fluid load.'),
  ('rodpump', 'advanced', 'module', 'm03-the-counterbalance', 8, 'balanceUnit takes a card load function and predictCard hands out only the decimated card. What does that do to peak torque on ODUMA-4?', '["Nothing, because the balance is a condition on two peaks and a stride pulls both of them in together, so the crossing the bisection finds is unmoved.", "It reads the torque 2.467917 percent high, because a coarse card exaggerates the two peaks that the bisection is driven to equalise.", "It reads 450016.096192 in-lb off the 186 point card against 461403.140996 in-lb off the full march, so the reported torque is 2.467917 percent low.", "It moves the counterweight moment from 609641.972281 in-lb to 601131.142443 in-lb and leaves the torque alone, since the torque is read once the balance has closed."]'::jsonb, 2, 'torquePct against the 320000 in-lb gearbox reads 140.630030060 percent from the default card and 144.188481561 percent from the full march, and near 100 percent that 2.467917 percent decides it.'),
  ('rodpump', 'advanced', 'module', 'm03-the-counterbalance', 9, 'The ODUMA-4 counterbalance effect is 13508.771698 lb from the default card and 13320.184195 lb from the full march. Why does 188.587503 lb matter more than its size suggests?', '["The effect is what a crew balances to at the polished rod, so a sampling choice nobody made has walked into a field target.", "It is the largest of the three movements the decimation makes, so a single number prices the whole of the sampling error in the balance.", "It carries the moment error with it at the same 1.415803 percent, so a crew hanging weights inherits the torque error a second time.", "It decides whether torqueOverload is raised, because that warning compares the counterbalance effect against the structural capacity of the unit."]'::jsonb, 0, 'The moment moves 1.415803 percent and the peak torque 2.467917 percent, and the effect, the one of the three that is quoted and measured in the field, moves 188.587503 lb.'),
  ('rodpump', 'advanced', 'module', 'm03-the-counterbalance', 10, 'Balance ODUMA-4 with a crank offset of -30.0 deg. Which field of that one return object does not know about the offset?', '["The peak torque, which is taken from a card the balance had already closed on, so the offset reaches the moment and stops there.", "The counterbalance effect, because balanceUnit does not forward crankOffsetDeg to counterbalanceEffect, which still reads the torque factor a quarter turn from the bottom.", "The counterweight moment, which is solved by bisection on the difference between the two peaks and so carries only their size and never where in the revolution either of them happened to fall.", "None of them, since the offset enters at the crank angle where the closure starts and every field downstream of the closure inherits it."]'::jsonb, 1, 'The moment reads 891505.531225 in-lb and the peak torque 592512.645044 in-lb, both of which read the offset, while the effect is reported as 19754.454642 lb from crank sample 89.'),
  ('rodpump', 'advanced', 'module', 'm03-the-counterbalance', 11, 'At a crank offset of -30.0 deg the reported ODUMA-4 effect is 19754.454642 lb and the effect at the true moment peak is 25368.233655 lb. What makes the offset the cause rather than a coincidence?', '["The gap of -22.129168 percent is the largest anywhere in the sweep, and a largest gap at the largest offset is what a cause looks like.", "The peak torque of 592512.645044 in-lb has moved with the offset as well, so the effect being wrong follows from the torque being wrong.", "At an offset of 0.0 deg the two agree to 0.000000 lb, while every row of the sweep reads the torque factor at the same crank sample 89.", "The engine''s own docstring says the factor is read where the moment is at its maximum, which names the assumption the offset breaks."]'::jsonb, 2, 'The moment peaks at crank sample 119 at that offset, where the torque factor is 35.142593819 in rather than 45.129341579 in, and only at a zero offset do the two land together.'),
  ('rodpump', 'advanced', 'module', 'm03-the-counterbalance', 12, 'Run ODUMA-4 with the balance left out. What do groups.torqueGroup and rating.torquePct come back as?', '["Both come back null, because the design knows the balance is missing and says so.", "torqueGroup reads 0.261911618, since the RP 11L chart needs no balance, and torquePct reads null because it needs the gearbox rating as well.", "torqueGroup reads 0.000000000 and torquePct reads 140.630030060 percent, which is the pair that makes an unbalanced run read as a healthy design.", "torqueGroup reads 0.000000000 where the real value is 0.261911618, and torquePct reads null."]'::jsonb, 3, 'One field knows it has no answer and the other reports a number: zero is the no load axis of the RP 11L torque chart, so a missing balance reads as a weightless gearbox.'),
  ('rodpump', 'advanced', 'module', 'm03-the-counterbalance', 13, 'Why is a torqueGroup of 0.000000000 worse than a merely unhelpful default?', '["Zero falls outside the range the chart accepts, so everything computed downstream of it is undefined rather than merely unknown.", "Zero is a meaningful point on the RP 11L torque chart, the no load axis, so the field reads as a result, and torquePct one field away already says not computed.", "It propagates into the peak polished rod load and the plunger stroke and the worst section loading, which are the fields a reader checks long before any of the RP 11L groups.", "It arrives with torqueOverload raised beside it, so a run with no balance reports a zero group and a gearbox warning at the same time."]'::jsonb, 1, 'The module already knows how to say not computed and does say it one field away, which is what makes the zero indefensible rather than unfortunate against the real 0.261911618.'),
  ('rodpump', 'advanced', 'module', 'm03-the-counterbalance', 14, 'What does a reader see in the rest of the return when the balance was left out of an ODUMA-4 design run?', '["Nothing: plunger stroke, peak polished rod load and worst section loading all come back equal to the balanced run, with ok true and no warnings.", "A shorter warning list, since torqueOverload cannot be raised without a balance and its absence is the sign that one was dropped.", "A peak polished rod load that has moved, because the balance enters the net torque and the net torque enters the card the loads are read from.", "A torquePct of 140.630030060 percent computed off the unbalanced card, which is the one trace the omission leaves in the object."]'::jsonb, 0, 'The balance enters two fields and nothing else, so the run lists a torqueGroup of 0.000000000 beside an Fo over Skr of 0.145616883 and an Sp over S of 0.923505123, which are real.'),
  ('rodpump', 'advanced', 'module', 'm03-the-counterbalance', 15, 'A balanced ODUMA-4 and an unbalanced one deliver the same polished rod horsepower of 18.955924637 hp. What does that say about what a balance asserts?', '["It says the weight returns on the downstroke everything it took on the upstroke, so a balance costs no energy and the two units buy the same motor.", "It says the horsepower was read off the same decimated card as the torque, so both numbers carry the sampling and neither of them carries the balance.", "It is a gearbox condition and nothing else, because polished rod power carries no gearbox loss, no belt loss, no motor efficiency and no counterbalance work.", "It says the balance moved only the crank angle at which the peak torque falls rather than its size, which is why a quantity integrated over the whole revolution comes back unmoved."]'::jsonb, 2, 'Polished rod horsepower is 18.955924637 hp either way while the peak torque halves, so a power number cannot be read as a check on the balance.'),
  ('rodpump', 'advanced', 'module', 'm04-inputs-that-do-nothing', 1, 'Which inputs does runRodPumpDesign destructure in its signature, list in its own documented input list and then never reference in its body?', '["The kinematics object, the damping ratio and the pump efficiency, all three of which reach only the card solver it calls internally.", "The structural unbalance, the crank offset and the gearbox rating, which are unit properties rather than string or pump properties.", "The kinematics object, the structural unbalance in lb and the crank offset in deg.", "The node count, the card sample count and the maximum cycle count, which the card solver holds its own defaults for."]'::jsonb, 2, 'All three belong to the balance of the unit, and the design function reads none of them, which ten outputs prove by strict equality with a count of differences of 0.'),
  ('rodpump', 'advanced', 'module', 'm04-inputs-that-do-nothing', 2, 'What is a structural unbalance physically, and where in this package is it read?', '["The standing load in lb that the beam structure itself puts on the polished rod, and balanceUnit reads it while the design function does not.", "The difference in lb between the peak and the minimum polished rod load, which is why it belongs beside the load range in the design return.", "The load in lb a unit is out of balance by at the moment a crew arrives, which is why the design accepts it and the balance recomputes it.", "The share of the rod weight in lb the counterweight fails to lift, which the Goodman check adds to the maximum stress in the top section."]'::jsonb, 0, 'The counterweight has to carry it, so it belongs to the balance: passed to balanceUnit at 600 lb it moves the counterweight moment from 609641.972281 in-lb to 574806.731952 in-lb.'),
  ('rodpump', 'advanced', 'module', 'm04-inputs-that-do-nothing', 3, 'Why is the test for an unread argument built on strict equality rather than on a tolerance?', '["A tolerance would have to be chosen, and choosing one on outputs in different units, from lb to bbl/d, is not defensible in a single test.", "Floating point arithmetic repeats exactly between two runs, so any tolerance would go unused.", "The oracle already holds the two independent routes to 2 percent on the plunger stroke, so a tolerance test would only repeat a check that exists.", "An input that is never read predicts agreement to the last bit, while a tolerance only answers whether the input mattered much."]'::jsonb, 3, 'Two numbers can agree to six figures because an input mattered a little; a value that enters any expression on the way to an output almost always disturbs its final figure.'),
  ('rodpump', 'advanced', 'module', 'm04-inputs-that-do-nothing', 4, 'The proof compares ten outputs rather than one. What decided which ten?', '["They are the ten the studio puts on the screen, so the proof is stated in exactly the numbers a user would have quoted off a design sheet.", "They span the whole function, reaching the pump, the march, the card, both load extremes, the power, the volumes and the stress check.", "They are the ten the oracle holds a gate on, so an unread input is proved against the same fields an independent route already checks.", "They are the ten with the most significant figures in the return, which is what gives strict equality something to bite on."]'::jsonb, 1, 'If either number had entered any stage of the calculation one of the ten would have moved, and the count of differences is 0, from a fluid load of 4690.299657039136 lb through to a worst section loading of 82.873308395930 percent.'),
  ('rodpump', 'advanced', 'module', 'm04-inputs-that-do-nothing', 5, 'Hand the design the kinematics of a generic 144 in unit, whose stroke is 143.997728 in, alongside a surface motion whose stroke is 106.687717 in. What comes back?', '["A warning that the two strokes disagree, since the design checks the kinematics it is given against the surface motion before it marches anything.", "A plunger stroke computed from the 144 in unit, because the kinematics argument overrides the surface motion wherever the two describe the same linkage.", "A plunger stroke of 98.526653099789 in, identical to the run with no kinematics at all, and no warning of any kind.", "A refusal, since a linkage that does not close is one of the errors this engine names."]'::jsonb, 2, 'kin is not merely unread, it is unchecked against the input it duplicates, so a caller can describe one pumping unit in one argument and a different one in the next.'),
  ('rodpump', 'advanced', 'module', 'm04-inputs-that-do-nothing', 6, 'A caller types a structural unbalance and a crank offset into runRodPumpDesign and reads back a gearbox rating percentage. What has happened?', '["The two numbers went nowhere, and the percentage is 140.630030060 rather than the 134.032962807 percent a balance that read them gives.", "The two numbers were applied to the balance but not to the card, so the percentage is right for the gearbox and wrong for the rods.", "The percentage is null, because the design cannot compute a torque rating from inputs it has accepted and not used.", "The percentage carries them at half weight, since only the structural unbalance reaches the torque and the crank offset is dropped."]'::jsonb, 0, 'Both figures are plausible and both sit above 100 percent, and nothing in the returned object says which one a reader is holding.'),
  ('rodpump', 'advanced', 'module', 'm04-inputs-that-do-nothing', 7, 'A structural unbalance of 600 lb and a crank offset of 10 deg are handed instead to balanceUnit. How large is what the design skipped?', '["The moment moves 8510.829838 in-lb, which is 1.415803 percent, and the peak torque 11387.044803 in-lb, which is 2.467917 percent.", "The counterweight moment moves 67531.101405 in-lb, which is 11.077174 percent, and the peak gearbox torque 21110.615211 in-lb, which is 4.691080 percent.", "Neither moves measurably, which is the reason the design function was written without reading them in the first place.", "Only the counterbalance effect moves, by 896.390132 lb, because the counterweight moment and the peak gearbox torque are properties of the card and of the linkage alone."]'::jsonb, 1, 'Those are not quiet values: with both passed the moment is 542110.870876 in-lb against 609641.972281 in-lb with neither, so the test was run on values large enough to show.'),
  ('rodpump', 'advanced', 'module', 'm04-inputs-that-do-nothing', 8, 'Ten outputs come back strictly equal with the two numbers passed and with them absent. What has that not proved?', '["That the inputs were accepted, since a rejected input would have raised one of the messages this engine is quick to give.", "That the plunger stroke is insensitive to the grid, which is a separate claim needing a node sweep rather than a second call.", "That the two values were large enough to matter, which is why the test is repeated far apart.", "That the answer is right, since both runs can be equally wrong and equality says only that they agree."]'::jsonb, 3, 'It also proves nothing about any other input or any branch those two values did not reach, and it cannot separate an input never read from one read and then multiplied by something that is zero on this case.'),
  ('rodpump', 'advanced', 'module', 'm04-inputs-that-do-nothing', 9, 'The rod pump oracle holds two independent routes to 2 percent on the plunger stroke and 3 percent on the minimum load. Why can that not catch an unread argument?', '["An ignored input produces a difference of exactly zero, and no tolerance detects zero.", "The oracle runs only the committed cases, and those cases pass a structural unbalance and a crank offset that happen to be small.", "The oracle compares the engine against a second implementation of the same function, which ignores the same three arguments for the same reason.", "The two routes are compared on the card rather than on the design return, so no field the three inputs would have reached is ever gated."]'::jsonb, 0, 'A checker built on agreement cannot find a value that nothing disagreed about, which is why the two call test with strict equality had to be run separately.'),
  ('rodpump', 'advanced', 'module', 'm04-inputs-that-do-nothing', 10, 'Five things in the stack could have caught an argument that is accepted and never read. Which list is right, and what happened?', '["The linter, the type declaration, the studio, the migration and the oracle, and only the studio showed the difference at all.", "The language, the documentation, the warning list, the studio and the oracle, and the warning list came closest by staying silent.", "The language, a type declaration, the documentation, the committed cases and the oracle, and none of the five raised anything.", "The parser, the closure check, the periodicity flag, the golden cases and the oracle, and the golden cases came nearest to it."]'::jsonb, 2, 'Destructuring an argument and never mentioning it is legal and silent, this package has no type declarations, the documentation lists all three, the committed cases do not pass them and the oracle cannot see a difference of zero.'),
  ('rodpump', 'advanced', 'module', 'm04-inputs-that-do-nothing', 11, 'Pass a crank offset of 10 deg to balanceUnit and the counterbalance effect moves from 13508.771698 lb to 12740.372690 lb. What does an equality test conclude there?', '["That the input was read and applied correctly, since a change of that size is the change the offset is expected to produce.", "That the input was read, which is true and not enough, because the reported effect is still wrong by 6.051664 percent.", "That the input was not read, because 6.051664 percent is too small a move for an offset of that size.", "Nothing, because an equality test compares two calls of one function and the effect is computed inside a function one layer down."]'::jsonb, 1, 'The offset reached the balance and not the line inside it that reads the torque factor, so change detected is not correctness and the true value at that offset is 12013.364233 lb.'),
  ('rodpump', 'advanced', 'module', 'm04-inputs-that-do-nothing', 12, 'This engine refuses a rod size it cannot read, a linkage that does not close, a plunger with no differential and a damping ratio of 0. How does that sit beside the three unread inputs?', '["It shows the refusals are the wrong ones, since an unread argument is a more serious fault than any of the four the engine names.", "It shows the three unread inputs are validated as well, because every argument the signature names passes the same input checks.", "It shows the refusals fire before the destructuring, so the three inputs are dropped at the point where the checks are made.", "It refuses badly formed input and accepts in silence input it will never use, and the run that passes all three raises no warning at all."]'::jsonb, 3, 'A wrong answer with an error beside it is a nuisance; a plausible answer with nothing beside it is the problem, and 140.630030060 percent arrives with an empty warning list.'),
  ('rodpump', 'advanced', 'module', 'm04-inputs-that-do-nothing', 13, 'How should the two values in a strict equality test be chosen?', '["Far enough apart to be seen where the input is read, since 600 lb and 10 deg move a balance by percent rather than by rounding.", "As near the shipped defaults as possible, so that any difference found is one a real caller would meet on a real design.", "At the two ends of the range the engine accepts, so that a refusal is triggered on one of the runs and the input is proved to be validated.", "At values that leave every output inside the oracle gates of 2 percent and 3 percent, so a difference cannot be confused with a route disagreement."]'::jsonb, 0, 'Widening the values is also the cheap way to separate an input that is never read from one that is read and then multiplied by something that happens to be zero on this case.'),
  ('rodpump', 'advanced', 'module', 'm04-inputs-that-do-nothing', 14, 'Given that the design ignores them, how does a caller get a torque percentage that carries a structural unbalance and a crank offset?', '["Pass them to the design and read torqueGroup instead of torquePct, since the RP 11L group is computed before the arguments are dropped.", "Scale the reported torque percentage by the ratio of the two balances, which on ODUMA-4 is the step from 140.630030060 to 134.032962807 percent.", "Solve the card, balance it with those two inputs passed to the balance, and quote the torque from the balance.", "Pass them twice, once to the design and once to the card solver it calls, so that the value reaches the march that the torque is read from."]'::jsonb, 2, 'A sheet listing a structural unbalance beside a torque percentage asserts a link, and here that link is made by hand, which is why the balance is run as its own step.'),
  ('rodpump', 'advanced', 'module', 'm04-inputs-that-do-nothing', 15, 'The equality test fails to move an output. What is the right conclusion to draw from it?', '["That the function is broken, which is the finding to report, since an argument in a signature is a promise the body has to keep.", "That on this call, with these values, that input went nowhere, and the next place to look is one layer down.", "That the output chosen was the wrong one, and the test should be repeated on a field the input would have been more likely to reach.", "That the input is read somewhere and cancels, because a value that enters any expression almost always disturbs the final figure of a result."]'::jsonb, 1, 'The narrow conclusion is the useful one: balanceUnit forwards structuralUnbalanceLb to counterbalanceEffect and does not forward crankOffsetDeg, so a pass at one level is not a pass at the next.'),
  ('rodpump', 'advanced', 'module', 'm05-stress-and-diagnosis', 1, 'Three quantities enter the modified Goodman allowable a rod section is judged against. Which of them is a property of the steel?', '["Only the grade minimum tensile, since the minimum stress comes off the card and the service factor is an opinion about the well.", "Only the service factor, which is published for each API grade and is what makes a grade D rod stronger than a grade K one.", "The tensile and the minimum stress, both of which are measured on the rods, while the service factor only scales the pair of them for the fluid.", "All three, because a fatigue line is a material property and the arithmetic behind it names nothing outside the rod."]'::jsonb, 0, 'Sa = ( T/4 + 0.5625 Smin ) SF, from API RP 11BR: the quarter tensile of grade D is 28750.000000 psi and the other two terms belong to the cycle and to the operator.'),
  ('rodpump', 'advanced', 'module', 'm05-stress-and-diagnosis', 2, 'Grade D at a service factor of 1 is allowed 28750.000000 psi at a minimum stress of 0.0 psi and 34375.000000 psi at 10000.0 psi. Why does the allowable rise?', '["A rod under a standing tension is stiffer, so the same load produces less strain and the line is drawn higher for it.", "The minimum stress is subtracted from the maximum before the comparison, so the line rises to keep the loading percentage unchanged.", "What damages steel is the swing, so a high floor means a smaller swing for the same peak and more is allowed.", "The allowable is a mean stress rather than an amplitude, so it has to rise with the minimum in order to stay above it."]'::jsonb, 2, 'The line adds 0.5625 of the minimum stress to the quarter tensile, which is why a string that never unloads is allowed more than one that swings to nothing.'),
  ('rodpump', 'advanced', 'module', 'm05-stress-and-diagnosis', 3, 'On ODUMA-4 at a service factor of 1.0000 the deepest section has an allowable of 27348.506758 psi, below the grade D quarter tensile. What put it there?', '["It is the section with the smallest area, and the allowable is scaled by area so that each section is judged against its own metal.", "Its minimum stress is -2491.543540 psi, and a negative minimum subtracts from the quarter tensile instead of adding to it.", "It sits at 3100.0 ft, and the line is reduced with depth to stand for the corrosion a deeper section meets.", "It carries the lowest maximum stress of the three, 20864.065937 psi, and the allowable follows the maximum stress down."]'::jsonb, 1, 'The same 28750.000000 psi stands behind all three allowables and they differ only because the minimum stresses do, so a section that goes into compression is judged more harshly.'),
  ('rodpump', 'advanced', 'module', 'm05-stress-and-diagnosis', 4, 'The three ODUMA-4 sections spread 6.583710 percentage points of loading at a service factor of 1.0000 and 7.745541 points at 0.8500. What do those two figures say?', '["The taper is stress balanced within the tolerance the engine holds, and the growth of the spread is round-off in the allowables.", "The spread is a property of the card rather than of the taper, which is why it moves when the service factor is changed.", "The bottom section is overworked at both factors, which is what a spread that grows as the line falls has to mean.", "The taper is not stress balanced, and the service factor divides into every loading, so lowering it stretches the gaps as well."]'::jsonb, 3, 'A taper is designed so every section works equally hard; here the top section carries the design at 82.873308 percent and the bottom holds margin nobody uses at 76.289598 percent.'),
  ('rodpump', 'advanced', 'module', 'm05-stress-and-diagnosis', 5, 'Walk the ODUMA-4 service factor from 1.0000 to 0.7000. What moves down that column, and what does not?', '["Only the line: the same maximum stress of 25210.199822 psi and the same minimum of 2969.187943 psi stand behind every row while the loading runs from 82.873308 to 118.390441 percent.", "The card is re-solved at each factor, because the factor enters the allowable and the allowable decides which section the design is worst in.", "The maximum stress falls with the factor while the minimum stress holds, which is what opens the loading up across the column.", "The allowable holds at 30420.168218 psi and the stresses move, since the service factor is applied to the stresses before they are compared."]'::jsonb, 0, 'Not one rod, one foot of depth or one stroke changed between those two readings, and the design is called acceptable at one end and overstressed at the other.'),
  ('rodpump', 'advanced', 'module', 'm05-stress-and-diagnosis', 6, 'Bisection puts the ODUMA-4 crossing at a service factor of 0.828733084. Why is that number not a surprise once the line is read?', '["The crossing sits at the ratio of the minimum stress of 2969.187943 psi to the maximum of 25210.199822 psi, which the line fixes.", "The line is linear in the service factor, so the crossing is the unity loading read as a fraction, and the loading at 1.0000 is 82.873308 percent.", "The bisection is run on the same sweep that produced the loadings, so the crossing has to land on one of the thirteen rows that were already computed.", "The crossing is where the allowable meets the quarter tensile of 28750.000000 psi, which is a property of the grade rather than anything the design chose."]'::jsonb, 1, 'At the crossing the allowable is 25210.199822 psi against a maximum stress of 25210.199822 psi and the loading reads 100.000000000 percent, so the arithmetic hides nothing and the judgement does all the work.'),
  ('rodpump', 'advanced', 'module', 'm05-stress-and-diagnosis', 7, 'At a service factor of 0.8200 the ODUMA-4 warning reads that the section runs at 101.1 percent of its allowable. What is missing from it?', '["The true loading, which is 101.065010 percent, because the message is formatted to a whole percent and reads as though the design sat on the threshold.", "The section it belongs to, which is why a reader has to recompute all three sections before the message can be acted on.", "The service factor that put it there, so a reader cannot tell a careful judgement from a generous one.", "The allowable of 25096.638780 psi, without which the percentage cannot be turned back into a stress a reviewer could check."]'::jsonb, 2, 'The message names the section and the percentage and never the factor, and one step of opinion away at 0.8300 the loading is 99.847360 percent with no message at all.'),
  ('rodpump', 'advanced', 'module', 'm05-stress-and-diagnosis', 8, 'A design comes back at a worst section loading of 97.498010 percent. What has the modified Goodman line refused to say about it?', '["Whether the string will last, because a loading is a comparison against a line rather than a life, and no fatigue history is modelled.", "Which of the three sections it belongs to, since the line is evaluated once for the whole string and the worst section is chosen afterwards.", "Whether the rods are in compression anywhere, which is a separate check the line has no term for.", "What the maximum stress behind it was, because a percentage carries no units and the stress has to be recovered from the allowable it was divided by."]'::jsonb, 0, 'T is a specified minimum for the grade rather than a measured strength for these rods, nothing in the arithmetic knows about corrosion, and 97.498010 percent is one step of service factor from 100.452495 percent.'),
  ('rodpump', 'advanced', 'module', 'm05-stress-and-diagnosis', 9, 'What makes diagnoseCard a different problem from predictCard rather than the same problem run backwards?', '["It marches the same wave equation from the surface downward instead of from the pump upward, so the time step is set by the measured sample spacing.", "It solves the same equation with the fluid load as the unknown, which is why it needs the plunger area the prediction was given.", "It fits the measured card to the predicted one and reports the fluid load that closes the gap, which is why the two share the card solver.", "Both the position and the load are known at the surface, so each Fourier harmonic is propagated down the string in closed form with no march and no time step."]'::jsonb, 3, 'This is the Gibbs 1963 problem, solved analytically one harmonic at a time, and the two solvers share no code path, which is what makes a round trip a real check.'),
  ('rodpump', 'advanced', 'module', 'm05-stress-and-diagnosis', 10, 'The published measured card runs from 0.000000 to 64.000000 in of position, and the diagnosis returns a plunger stroke of 79.499400953 in. Why is the pump stroke the longer one?', '["The plunger stroke is measured in the fluid and the surface stroke in air, and buoyancy lengthens the travel the pump sees.", "The string is still moving when the surface reverses, so the plunger travels further than the polished rod, a ratio of 1.242178140 here.", "The harmonic sum adds the stretch of the string to the surface stroke, because a rod that stretches under load must give the plunger the extra travel.", "The measured card was recorded over a slow cycle at 9 spm, so the plunger overshoots by an amount that would vanish at a field speed."]'::jsonb, 1, 'Reading a surface stroke as a pump stroke is not a small error on this card: 64.000000 in at the polished rod implies 79.499401 in at the plunger.'),
  ('rodpump', 'advanced', 'module', 'm05-stress-and-diagnosis', 11, 'Sweep the harmonic count on the published measured card from 2 requested to 58. Every row returns a plunger stroke of 79.499400953 in. What does that establish?', '["That the harmonic count is not read, since a resolution knob that changes no output is an input accepted and never used.", "That the cap of floor(N/2) - 1, which is 59 for a 120 point card, is reached well before 58 and the extra harmonics are discarded.", "That this card is smooth enough to carry almost nothing above its lowest harmonics, which is a property of the card and not a licence to use two.", "That the diagnosis has converged in harmonics, so any measured card can be read at two harmonics without loss."]'::jsonb, 2, 'A measured card with a sharp valve transfer in it carries a great deal above the low harmonics, and there the count decides how much of that transfer survives.'),
  ('rodpump', 'advanced', 'module', 'm05-stress-and-diagnosis', 12, 'Hand diagnoseCard a measured card of twelve samples. What does it do?', '["It refuses, returning ok false with a message that a dynamometer card needs at least sixteen samples to be read.", "It pads the card to sixteen samples by interpolation and warns that the result rests on a card below the intended resolution.", "It returns a stroke computed from the two harmonics a twelve point card supports, since the cap of floor(N/2) - 1 is still positive there.", "It accepts the card and raises notPeriodic, because a card too short to close cannot be shown to repeat."]'::jsonb, 0, 'Sixteen samples is the floor, and the refusal comes back as a message rather than as a stroke computed from too little.'),
  ('rodpump', 'advanced', 'module', 'm05-stress-and-diagnosis', 13, 'The ODUMA-4 round trip gives a plunger stroke of 98.826085067 in from the diagnostic against 98.526653100 in from the march. What is that 0.303910 percent the price of?', '["The truncation alone, because the surface card is exact and the only approximation left in the route is the harmonic sum.", "The march alone, because the diagnostic is a closed form solution and a closed form carries no discretisation error to contribute.", "The damping ratio alone, since the two solvers were run at different damping and the stroke is the field most sensitive to it.", "The whole round trip, since the diagnostic sees only the decimated card and only the harmonics it is given, and neither solver can be charged with it alone."]'::jsonb, 3, 'The surface card handed over holds 186 points decimated from 6110 marched steps, so a diagnosis is a reading of a reading and 24 harmonics were used out of a cap of 92.'),
  ('rodpump', 'advanced', 'module', 'm05-stress-and-diagnosis', 14, 'The round trip stroke difference reads 0.606264751 in at 4 harmonics, 1.664923714 in at 6, 0.252191287 in at 16 and 0.344508847 in at 91. What does that sequence rule out?', '["Using fewer than sixteen harmonics on any measured card, since the two lowest rows of the sweep show the error falling steadily up to that point.", "The claim that the two solvers agree at all, because a difference that does not settle to a limit cannot be read as agreement between two routes.", "Refining the harmonic count until the answer stops moving, because past sixteen the difference settles into a band instead of shrinking.", "Reading the pump load extremes at all, which is a separate objection resting on the overshoot of 246.133034826 lb at the top of the card rather than on this column."]'::jsonb, 2, 'Four harmonics beat six, and 91 harmonics is worse than 16, so the count is a choice to be defended rather than a knob to be turned up.'),
  ('rodpump', 'advanced', 'module', 'm05-stress-and-diagnosis', 15, 'Read the same ODUMA-4 card back at damping ratios of 0.0500 and 0.2000. What happens to the minimum pump load?', '["It holds near -207.880450 lb, because the minimum pump load is fixed by the measured card and the damping enters only the stroke.", "It goes from -1487.766564 lb to 40.250811 lb, so whether the plunger is in compression is settled by a number the analyst typed.", "It falls further with damping, from -1487.766564 lb toward the -474.905243 lb at 0.1000, since more damping removes more energy on the way down.", "It is refused outside the band of about 0.05 to 0.15 of critical, so the reading at 0.2000 does not come back at all."]'::jsonb, 1, 'Damping is not measurable from a card and the engine refuses only the value 0, while the plunger stroke read back moves 1.402208257 in across that sweep.'),
  ('rodpump', 'advanced', 'module', 'm06-the-expert-reading', 1, 'Sort a rod pump design sheet into measurements, conventions and artefacts of sampling. Which grouping is right?', '["The loads are the measurements, since they come off the card the march produced, while the stroke is a convention of how the pump node is read.", "Everything the engine returns is a measurement, and only the warnings are conventions, since a threshold is the one place in the whole return where a person chose a number outright.", "The service factor is an artefact of the sampling, because the loading it scales was read off a card whose stride nobody chose.", "The plunger stroke is the nearest thing to a measurement, the service factor and the 0.85 fillage line are conventions, and the subsample and the node count are artefacts."]'::jsonb, 3, 'The stroke moves 0.044644 percent across six node counts, the subsample and the grid move the loads far more, and neither the service factor nor the fillage threshold is physics.'),
  ('rodpump', 'advanced', 'module', 'm06-the-expert-reading', 2, 'Why can a produced rate be defended off a rod pump design while a load range has to be qualified?', '["The produced rate is checked against the rated displacement, which is a closed form, so any error in the march cancels out of the ratio.", "Everything proportional to the plunger stroke survives the grid, and the stroke moves 0.044644 percent from 60 to 1920 nodes while the minimum load moves 10.864298 percent of the smallest.", "The load range is narrowed by the decimation at one end only, so its lower half is defensible and its upper half is not.", "The rate is reported to fewer figures, so the grid movement in it falls below the precision the design chose to print."]'::jsonb, 1, 'A stroke is a peak to trough of a position over a whole cycle and the loads are point values of a derivative, so the two survive a change of grid very differently.'),
  ('rodpump', 'advanced', 'module', 'm06-the-expert-reading', 3, 'The order of work starts with the string rather than the card. Why check the note before anything is marched?', '["The engine refuses a design at or above the string''s own fundamental with the number in the message, so a speed that is too high is a refusal rather than a strange card to be explained later.", "The fundamental sets the time step the march is allowed, so a card solved before it is known has to be discarded and solved again.", "The scan that finds it walks a quadratic grid, so it has to be run while the string is short enough for the grid to bracket the root.", "The note fixes the damping ratio, and the march refuses a damping ratio of 0, so nothing can be solved until the note is in hand."]'::jsonb, 0, 'At 60 strokes a minute on a string whose fundamental is 59.1 spm the run is refused outright, and the message says nothing predicted there would be trustworthy.'),
  ('rodpump', 'advanced', 'module', 'm06-the-expert-reading', 4, 'What has to be written down beside every load a design run returns, and why?', '["The service factor, because a load is compared against the modified Goodman line and that line is the one place where a chosen number enters the design at all.", "The gearbox rating and the structural capacity of the unit, because a load has no meaning on a design sheet until it is expressed as a percentage of what the unit can carry.", "The card sampling and the node count, because a load is a claim about the well and about the sampling together and only one of those is in the answer.", "The pumping speed and the damping ratio, because those two set the wave and everything downstream of the wave inherits them."]'::jsonb, 2, 'runRodPumpDesign forwards neither, so the shipped values are what a reader gets: cardSamples 180, which keeps 186 points, nodes 120, maxCycles 20 and tol 0.0001.'),
  ('rodpump', 'advanced', 'module', 'm06-the-expert-reading', 5, 'Why is there no order of work in which one call to runRodPumpDesign returns a balanced design?', '["The balance is refused unless the card it is given has already been checked for periodicity, which only a completed design run reports.", "The design returns the balance in torqueGroup and torquePct, so a second call is needed only when the gearbox rating is to be checked as well.", "The card solver is not exported, so a balance can only ever be run on a measured card handed in from a dynamometer.", "balanceUnit needs a surface card and the design calls the card solver internally, so the card has to be solved, balanced, and then the design run, which solves the same card again."]'::jsonb, 3, 'That is why the natural first call is the one with the balance left out, and it comes back with a torqueGroup of 0.000000000 rather than the real 0.261911618.'),
  ('rodpump', 'advanced', 'module', 'm06-the-expert-reading', 6, 'One design return carries two peak polished rod loads. Which check reads which, and what does a reader owe that pair?', '["The Goodman line reads the envelope and the structural rating reads prlPeakLb, so a load has to be named by its route before it is compared with anything.", "The Goodman line reads prlPeakLb and the structural rating reads the envelope, which is what keeps the structural check the conservative one of the two routes.", "Both read the tension envelope, and prlPeakLb is kept only for the plot, so the pair costs a reader nothing at all as long as the plotted number is not quoted.", "Both read prlPeakLb, and the envelope is a diagnostic field, so the two numbers in the object are two ways of printing one load."]'::jsonb, 0, 'The envelope implies 19851.465785541 lb where prlPeakLb reports 19545.877783339 lb, a disagreement of 1.563440 percent inside a single call.'),
  ('rodpump', 'advanced', 'module', 'm06-the-expert-reading', 7, 'The worst section loading dips 1.470226 percentage points at one speed in a sweep. What settles whether that dip is an operating point?', '["The convergence flag on the three rows, since a dip made of converged rows is a property of the well and not of the solver.", "The node spread on the same design, 4.283675 percentage points at one speed and 6.553883 at another, which is larger than the dip.", "Whether the plunger stroke dips with it, because a real optimum has to show in the stroke and the loads together.", "The oracle tolerance of 3 percent on the minimum load, which is the smallest difference any number reported out of this engine is allowed to carry."]'::jsonb, 1, 'The dip is 0.343216 times the first spread and 0.224329 times the second, so a parameter with no physical content moves the number further than the speed change did.'),
  ('rodpump', 'advanced', 'module', 'm06-the-expert-reading', 8, 'Two ODUMA-4 designs make 301.389964 bbl/d and 301.354487 bbl/d and only one raises incompleteFillage. What is the reading habit that follows?', '["Treat the warned design as the conservative one of the pair, since a threshold is set where the physics changes and the warning marks the crossing.", "Re-run both of them at a finer node count, because a warning that separates two designs sitting so close together is a sign the march has not settled.", "Read the number rather than the warning list, because a warning is a filter set at a chosen place and those two designs are 0.035477 bbl/d apart.", "Quote the warned figure only, since a design that raises a warning is the one a reviewer will ask about and the other is inside it."]'::jsonb, 2, 'Nothing measurable separates them, and the same habit covers the periodicity flag, which can be raised at one node count and not at a coarser or a finer one.'),
  ('rodpump', 'advanced', 'module', 'm06-the-expert-reading', 9, 'Several of the faults this tier priced are reporting faults. Which repair changes no equation?', '["Giving counterbalanceEffect the crank offset the balance around it already holds, which at 20.0 deg moves the reported effect from 12393.212710 lb to 11287.785540 lb.", "Raising the node count until the two load extremes stop moving, which costs only run time and leaves the physics untouched.", "Widening the fillage threshold into a band, so that two designs a few ten thousandths apart are treated the same way.", "Reporting the minimum polished rod load from the envelope rather than the card, which removes the sampling error from the load range."]'::jsonb, 0, 'A design function could forward the three inputs it already accepts and a load could be reported with the sampling that produced it, and none of that touches an equation.'),
  ('rodpump', 'advanced', 'module', 'm06-the-expert-reading', 10, 'A rod pump design passes every check this engine makes. What can it still fail on in the field?', '["A speed above the string''s own fundamental, since that refusal is raised only when the note has been computed separately from the design that is being checked.", "An unconverged march, because the periodicity flag is reported rather than checked, so a design can pass every gate with the march still settling toward a repeating stroke.", "A counterweight moment the crank cannot physically carry, which is the one limit of the unit that the balance returns no field about and is unable to assert.", "Rod buckling, tubing movement, gas interference, rod on tubing wear and the fatigue history that turns a loading percentage into a service life."]'::jsonb, 3, 'None of those appears in a warning, because the package models a string, a linkage, a pump and a wave and nothing outside them.'),
  ('rodpump', 'advanced', 'module', 'm06-the-expert-reading', 11, 'Why is a worst section loading of 82.873308 percent not a reportable number on its own?', '["It is read off the decimated card, so it has to be quoted with the stride that produced it rather than with any judgement.", "The service factor decides it, and on this design the crossing to overstressed sits at 0.828733084 with the card unchanged either side.", "It is the worst of three sections and the other two have to be quoted with it, since a spread of 6.583710 percentage points is not stress balanced.", "It carries no grade, and the same percentage against API Grade K rather than grade D would be a different design."]'::jsonb, 1, 'A loading percentage is a comparison against a line somebody chose, so the factor goes beside the percentage or the percentage means nothing.'),
  ('rodpump', 'advanced', 'module', 'm06-the-expert-reading', 12, 'What are the three questions to put to any number on a rod pump design sheet?', '["What refused it, what warning it would have raised, and whether the oracle holds an independent gate on the field it was read out of.", "Which of the engines returned it, which published case that engine was validated against, and how many figures the studio printed it to.", "What sampled it, what convention set its threshold, and would it survive a grid parameter that changes nothing about the well.", "Which of the checks reads it, which field unit it is quoted in, and whether the design run it came out of reported that it had converged in time."]'::jsonb, 2, 'The tier''s own answers are a 186 point subsample, a service factor of 0.828733084 and a stroke that moves 0.044644 percent across six node counts.'),
  ('rodpump', 'advanced', 'module', 'm06-the-expert-reading', 13, 'The gearbox torque a design reports on ODUMA-4 is 450016.096192 in-lb. What does a torque percentage on a design sheet actually assert?', '["That a card was solved, decimated and balanced, and it reads 2.467917 percent low against the same balance taken off the full march.", "That the structural unbalance and the crank offset on the sheet beside it were carried into the number, since the design accepts both.", "That the peak torque was accumulated over every marched step, as the tension envelope is, so the sampling reaches the loads and not the torque.", "That the counterweight moment is achievable on the crank, which is the one thing the balance checks before it returns."]'::jsonb, 0, 'Off the full march card the same balance gives 461403.140996 in-lb, and the two numbers the design would not read reach the torque only if the balance is run by hand.'),
  ('rodpump', 'advanced', 'module', 'm06-the-expert-reading', 14, 'The diagnostic reads the ODUMA-4 surface card back and returns 98.826085067 in against the march''s 98.526653100 in. Why does the tier lean on that pair?', '["The diagnostic is exact, so the gap is the whole of the error in the march and can be subtracted from the reported stroke.", "Two solvers sharing no code path agree to 0.303910 percent on the one quantity that also survives a change of grid.", "It is the only number in the design the oracle holds an independent route to, which is what makes it checkable at all.", "The two were computed from the same 6110 marched steps, so the agreement rules out the decimation as a source of error."]'::jsonb, 1, 'The plunger stroke moves 0.044644 percent from 60 to 1920 nodes and comes back within 0.299431967 in from a wholly different mathematics, which is as close to a measurement as this engine gets.'),
  ('rodpump', 'advanced', 'module', 'm06-the-expert-reading', 15, 'A reviewer is handed a load range, a produced rate and a torque percentage from one design run. Which needs the least qualification?', '["The load range, since the peak and the minimum come out of one march and the two sampling errors cancel in their difference.", "The torque percentage, because the balance drives the difference between two peaks to zero and a bisected result carries no sampling.", "The produced rate, because it follows the plunger stroke, which converges on the grid and is untouched by the card decimation.", "None of the three, since every number in the return is read off the same decimated card and inherits the same stride."]'::jsonb, 2, 'The stroke reads 98.526653100 in at the default sampling and at stride 1, while the reported loads and the balanced torque both move with the sampling.'),
  ('rodpump', 'advanced', 'final', null, 1, 'A load range of 16920.405078 lb is going onto a design sheet a workover crew will act on. What has to be written beside it?', '["Nothing, because the range is a difference of two loads taken from one card, so whatever the sampling did to each of them cancels in the subtraction.", "That it was read off a 186 point card, because the march found 17819.156290 lb and the reported range is pulled in at both ends.", "The node count it was computed on, because the load range is the one reported quantity a grid refinement leaves alone and a reader has to be told which grid to repeat.", "The service factor, because a load range is what the modified Goodman line is applied to and the line moves with the factor while the design does not."]'::jsonb, 1, 'The reported peak is 377.772986 lb low and the reported minimum 520.978227 lb high, so the two errors add rather than cancel and the range comes back 898.751212 lb narrow.'),
  ('rodpump', 'advanced', 'final', null, 2, 'The ODUMA-4 march computes 6110 steps in a cycle and the surface card that comes back holds 186 points. What produced that count?', '["The march keeps only the steps at which the load moved by more than the tolerance of 0.0001, and on this well 186 steps cleared it.", "The card carries one point for each of the 120 interior nodes plus the settled part of the cycle, which is where the extra points come from.", "The march settles after 4 cycles and only the last of them is returned, so the card is one cycle of the four the solver ran.", "cardSamples defaults to 180, so the recorded steps are decimated at a stride of 33 and 186 of them survive into the card."]'::jsonb, 3, 'The card keeps 3.044190 percent of the steps the march computed, and prlPeakLb and prlMinLb are the maximum and minimum of that surviving subsample.'),
  ('rodpump', 'advanced', 'final', null, 3, 'sectionStresses reads the tension envelope and never touches the decimated card. Which input to a Goodman verdict on ODUMA-4 is therefore the one worth pressing on?', '["The card sample count, since the envelope is accumulated from the same march the card is decimated from, so a coarser card feeds a coarser envelope into the stresses.", "The rod grade, since the minimum tensile of 115000 psi fixes T over 4 and therefore fixes every allowable the three sections are judged against.", "The service factor, since walking it from 1.0000 to 0.7000 takes the loading from 82.873308 to 118.390441 percent while the card, the stresses and the envelope never change.", "The node count, since the envelope is sampled at 120 interior nodes and each section is priced at whichever of those nodes falls nearest its top."]'::jsonb, 2, 'The design never changes down the service factor column: only the line it is judged against moves, and the crossing at 0.828733084 is where an acceptable design becomes an overstressed one.'),
  ('rodpump', 'advanced', 'final', null, 4, 'A studio user suspects the reported loads on a design are subsampled. What must they actually do to see the other pair of numbers?', '["Solve the card separately through predictCard, which accepts cardSamples and nodes, and read the loads off the finer card.", "Raise maxCycles above its default of 20 in the design call, since the loads settle further with every extra marched cycle and the card is written on the last one.", "Compare the reported peak with the reported minimum, because a decimated card narrows the load range at both ends while an undecimated one does not.", "Read the warning list, since the engine raises the timestep warning whenever the card it returns holds fewer points than the march computed."]'::jsonb, 0, 'runRodPumpDesign forwards neither cardSamples nor nodes, so the shipped 180 and 120 are what a studio user gets and predictCard is the only way in.'),
  ('rodpump', 'advanced', 'final', null, 5, 'Which single reported quantity on ODUMA-4 is unchanged between the default card and the fully marched one, and why does that matter to somebody hunting the subsample?', '["Polished rod horsepower, which follows the card area and therefore survives any stride the decimation chooses.", "Plunger stroke, 98.526653100 in at both, a difference of 0.000e+0 in, so it cannot be used as a check that the sampling moved anything.", "The load range, since the peak and the minimum are pulled in by the same stride and the two errors cancel in the difference.", "The worst section loading, because it is computed from the tension envelope and the envelope is accumulated over every marched step."]'::jsonb, 1, 'The plunger stroke is a peak to trough of the pump node over every marched step and is never decimated, so it reads 98.526653100 in at the default and at stride 1.'),
  ('rodpump', 'advanced', 'final', null, 6, 'Run ODUMA-4 at 12.0 spm and the reported minimum polished rod load is 45.754029 lb. What did the march find, and what does the pair assert?', '["The march found 45.754029 lb as well, since a sign is the one feature a coarse stride cannot lose.", "The march found 1464.558895 lb, so the reported card understates the load the rods carry at the bottom of the stroke.", "The march found -466.104183 lb, so the two disagree about whether the rods go into compression at all.", "The march found -1115.467356 lb, and the reported figure is the same load with the buoyed rod weight of 9466.342675 lb added back at the surface."]'::jsonb, 2, 'A negative minimum means the polished rod is pushing down, which is the single verdict the minimum exists to deliver, and at 12.0 spm the reported number delivers the opposite one.'),
  ('rodpump', 'advanced', 'final', null, 7, 'Hold ODUMA-4 still and empty the barrel. What happens to the gap between the reported minimum and the marched minimum, and why?', '["It widens sharply, to a reported over marched ratio of 7.188966 at a fillage of 0.7000, because a partly filled barrel sharpens the load transfer the coarse card is missing.", "It closes, because a lower fillage shortens the plunger stroke and a shorter stroke is resolved by the same 186 points more finely.", "It stays at 1.247555046, since the ratio is a property of the stride of 33 and the stride does not move with fillage.", "It reverses, so that the reported minimum comes back low instead of high once the fillage drops under the 0.85 warning threshold."]'::jsonb, 0, 'At a fillage of 0.7000 the reported minimum is 1161.037714 lb where the march found 161.502733 lb, so the size of the error is a property of the case and not of the engine.'),
  ('rodpump', 'advanced', 'final', null, 8, 'Two ODUMA-4 numbers are read off the same 186 point card: the structural rating and the balanced peak gearbox torque. Which of the two is moved further by lengthening that card to the full march?', '["The rating percentage, because it is a ratio against a fixed capacity of 19800 lb and a ratio magnifies whatever the sampling did to its numerator.", "Neither, because the balance drives the two torque peaks to a difference of 0.0000e+0 in-lb on whichever card it is handed, so a balanced torque is free of the sampling.", "They move together and by the same fraction, because a torque is the torque factor times the polished rod load and the torque factor is geometry alone.", "The peak torque, by 2.467917 percent, against the 1.896103 percent the rating percentage inherits through its peak load."]'::jsonb, 3, 'The decimation moves the peak gearbox torque by 11387.044803 in-lb and the default card reads it low, so a balance solved on a subsample carries that subsample one level further than the structural check does.'),
  ('rodpump', 'advanced', 'final', null, 9, 'Two separate effects push the reported peak on ODUMA-4 below the march. How should an expert keep them apart?', '["Both are the same effect at two scales, so quoting the larger of them, 1.563440 percent, states the whole of it.", "The subsample costs 1.563440 percent and the half node of rod the envelope grid cannot resolve costs 0.259029 percent, so one is a sampling choice and the other a discretisation choice.", "The half node is the larger of the two, at 51.421146497 lb of buoyed rod against a load range of 16920.405078 lb, and the subsample is a rounding difference beside it.", "Neither can be separated from the other without a node sweep, because the envelope spacing and the card stride are set by the same default."]'::jsonb, 1, 'Confusing them flattens a 1.563440 percent problem into a 0.259029 percent one, and only the first is a sampling choice anybody would call wrong.'),
  ('rodpump', 'advanced', 'final', null, 10, 'Why does raising the node count on a rod pump march raise the number of steps in a cycle?', '["The engine marches one step per node per cycle, so the step count is the node count times the number of cycles it takes to settle.", "Finer grids need more cycles to settle, and the step count is the cycles marched times the fixed step of 9.819967e-4 s.", "The march is explicit, so the time step follows the Courant condition and has to shrink with the node spacing.", "The wave speed rises on a finer mesh, so the string is traversed more often in the same stroke period and each traverse costs its own steps."]'::jsonb, 2, 'On ODUMA-4 the steps go 3055, 6110, 12219, 24437, 48874 and 97747 as the nodes double from 60 to 1920, so the cost of a run rises as the square.'),
  ('rodpump', 'advanced', 'final', null, 11, 'Across six node counts from 60 to 1920 on ODUMA-4 at the shipped damping, which quantities settle and which do not?', '["The plunger stroke moves 0.044644 percent while the peak load moves 1.683064 percent and the minimum 10.864298 percent of the smallest in size.", "All three settle, since every one of the six rows reports converged and a converged march is a mesh converged march.", "The two loads settle and the plunger stroke does not, because a stroke is read at one node while the loads are accumulated over all of them.", "None of them settles, so nothing computed on this well can be quoted without a stated grid uncertainty beside it."]'::jsonb, 0, 'A quantity proportional to the plunger stroke, including the swept and produced rates, survives the grid, and anything built on the load extremes does not.'),
  ('rodpump', 'advanced', 'final', null, 12, 'What is the structural reason the plunger stroke survives a node refinement when the two load extremes do not?', '["The stroke is computed before the march begins, from the surface stroke and the static stretch, so no grid enters it.", "The stroke is reported at the pump node, which is a boundary the mesh always lands on exactly, while the loads are read at interior nodes that move with the grid.", "The stroke is bounded by the surface stroke of 106.687716837 in, and a bounded quantity cannot wander with the mesh.", "A stroke is a peak to trough of one node position over a whole cycle, and a position is an integral of the wave, while the loads are point values of a spatial derivative."]'::jsonb, 3, 'Integrating smooths and differentiating roughens, which is why the stroke moves 0.044644 percent while the peak moves 1.683064 percent over the same six grids.'),
  ('rodpump', 'advanced', 'final', null, 13, 'What does the ODUMA-4 peak load column do as the node count is walked from 60 to 1920, and what does that rule out?', '["It rises at every row toward 19923.650769 lb, which is the answer a fully sampled card would give.", "It falls monotonically toward the envelope route, so the coarse grids are the ones overstating the load.", "It rises through 240 nodes, falls at 480 and 960 and rises again at 1920, so refining until the answer stops changing is not available.", "It stays inside 0.044644 percent, the same band the plunger stroke holds, so the loads are converged after all."]'::jsonb, 2, 'The peak reads 19337.292600, 19545.877783, 19662.751698, 19551.233793, 19520.004895 and 19590.579526 lb down those six rows, so the answer changes back.'),
  ('rodpump', 'advanced', 'final', null, 14, 'At 11 spm and a damping ratio of 0.05 the worst section loading on ODUMA-4 spreads 6.686252312 percentage points across six grids. What survives that spread?', '["Nothing, since a quantity that moves by more than six percentage points under a parameter that changes nothing about the well cannot support a verdict either.", "The verdict, since every one of the six rows sits above 100 percent, so the design is overstressed on any grid even though no row is a reportable figure.", "The plunger stroke, which moves only 1.893435110 in over the same six rows and is therefore the one quantity in the sweep that may still be quoted.", "The mean of the six rows, which is the estimate the spread is the uncertainty on, so the design is reported at that mean with the spread beside it."]'::jsonb, 1, 'A spread that swamps the figures need not swamp the finding: the six rows run from 106.108866698 to 112.795119010 percent and not one of them is acceptable.'),
  ('rodpump', 'advanced', 'final', null, 15, 'The notPeriodic message offers more damping or a look at the inputs, and says nothing about resolution. What can a caller holding only runRodPumpDesign do about it?', '["Nothing that reaches the cause, because the flag tracks the grid and neither nodes nor maxCycles is forwarded, while the damping ratio it does offer stands for a property of the well.", "Raise the damping ratio, which is an input the design function takes and which clears the flag on any grid, since a more heavily damped string always settles sooner into a repeating cycle.", "Raise maxCycles above its default of 20, since a run that stopped at 20 cycles was still settling and the flag is raised by the stop rather than by the grid it was computed on.", "Read the flag as a refusal and stop, since the engine raises it only when the loads it computed are unusable and the message names the two things that would make them usable."]'::jsonb, 0, 'At 11 spm and a damping of 0.05 the flag reads false, false, false, true, false and true down six grids, and the design function exposes neither of the two parameters that produced that sequence.'),
  ('rodpump', 'advanced', 'final', null, 16, 'Sweeping the speed on ODUMA-4 the worst section loading dips 1.470226 percentage points at 10.6 spm. What settles whether that is an optimum?', '["The converged flag on the three rows, which reads true at every one of them, so the march settled into a repeating stroke at each speed and the dip is a settled answer.", "A finer speed step between 10.4 and 10.8 spm, which would show whether the dip is a single row or a genuine trough with rows falling away on either side of it.", "The plunger stroke at the same three speeds, since a real optimum in the loading has to show up as a stroke that moves with it rather than against it.", "The node spread on the same quantity, 4.283675 percentage points at 10.4 spm and 6.553883 at 10.8 spm, which is larger than the dip."]'::jsonb, 3, 'The dip is 0.343216 times the node spread at the row before it and 0.224329 times the spread at the row after it, so a parameter with no physical content moves the number further than the speed does.'),
  ('rodpump', 'advanced', 'final', null, 17, 'Why can the node spread on ODUMA-4 not be measured once and carried through a sweep?', '["It falls steadily with speed, so a spread measured at the lowest speed in a sweep bounds every row above it.", "It is fixed by the 120 node default and the string length of 4800 ft, so one measurement covers any speed on this well.", "It is 2.104178 percentage points at 10.2 spm, 4.283675 at 10.4 spm, 0.936333 at 10.6 spm and 6.553883 at 10.8 spm, so the floor is different at every speed.", "It cannot be measured at all, because the design function does not expose the node count, so a sweep has to be read exactly as the solver printed it and the floor stays unknown."]'::jsonb, 2, 'A reader comparing 85.051352 percent at 10.2 spm with 89.649462 percent at 10.4 spm has to clear both floors, 2.104178 and 4.283675 percentage points, before calling the difference real.'),
  ('rodpump', 'advanced', 'final', null, 18, 'What does balanceUnit actually solve for, and what does balanced mean numerically on ODUMA-4?', '["The counterweight moment that minimises the net gearbox torque through the whole revolution rather than at its two peaks, which on this unit is the 609641.972281 in-lb the bisection returns.", "One scalar condition in one unknown, closed by bisection, until the largest upstroke torque and the largest downstroke torque differ by 0.0000e+0 in-lb at 450016.096192 in-lb each.", "The counterweight moment at which the net torque never changes sign, so the gearbox always turns the same way.", "The counterweight that makes the polished rod load itself equal on the upstroke and on the downstroke, which is what a closed dynamometer card asserts about a unit whose weights are hung right."]'::jsonb, 1, 'The condition is on two peaks only, so the peak torque is whichever of the two you like, and the 450016.096192 in-lb figure is the number the unit is bought against.'),
  ('rodpump', 'advanced', 'final', null, 19, 'Dividing the ODUMA-4 counterbalance moment by the front arm gives 5715.391704 lb. Why is that not the counterbalance effect?', '["The front arm of 106.6667 in is the stroke divided by the beam angle sweep and is not a lever arm at all, so the quotient has no units of load.", "The moment is quoted at the bottom of the polished rod stroke and the effect a quarter turn later, so the two differ by the ratio of the torque factors at those two crank positions.", "The moment acts through the crank and the torque factor, not through the beam arm, so the division understates the effect by a factor of 2.363578.", "The division omits the structural unbalance, and adding 600 lb back brings 5715.391704 lb to the reported 13508.771698 lb."]'::jsonb, 2, 'The reported effect is 13508.771698 lb, read where the torque factor is 45.129341579 in, and a crew set to 5715.391704 lb would run a unit reading well below its own rod weight.'),
  ('rodpump', 'advanced', 'final', null, 20, 'The ODUMA-4 counterbalance effect is 13508.771698 lb. What does a field crew check it against?', '["The buoyed rod weight of 9466.342675 lb, which it sits 4042.429023 lb above, roughly the rod weight plus half the fluid load of 2345.149829 lb.", "The peak polished rod load of 19545.877783 lb, which a balanced unit''s counterweight has to match so that the gearbox sees no net torque at the top of the upstroke.", "The gearbox rating of 320000 in-lb, converted into a load at the polished rod through the front arm of the unit and the upstroke fraction of the linkage.", "The fluid load of 4690.299657 lb, which is what the counterweight lifts on its own during the upstroke while the rods are carried by the beam and the structure."]'::jsonb, 0, 'The engine lands on the crew''s rule of thumb without being told to, which is what makes 13508.771698 lb readable rather than merely returned.'),
  ('rodpump', 'advanced', 'final', null, 21, 'Sweeping the ODUMA-4 counterweight moment past the balance point moves the upstroke peak down and the downstroke peak up. What does the gearbox see?', '["The upstroke peak alone, since that is the half of the cycle in which the rods and the fluid are both being lifted and the counterweight is falling rather than being raised by the crank.", "The average of the two, which is why the balance point is a minimum in the mean and not in either peak.", "The downstroke peak only once the moment passes twice the balanced value of 609641.972281 in-lb, and nothing below that point costs the gearbox anything it was not already carrying.", "The larger of the two at every point, so at 1.2500 of the balanced moment it sees the downstroke peak of 599096.054316 in-lb and overweighting costs as surely as underweighting."]'::jsonb, 3, 'At zero moment the two peaks are 950041.862527 and 646133.044285 in-lb and at 1.2500 they are 325168.729223 and 599096.054316 in-lb, so the crossing at the balance is a minimum of the larger.'),
  ('rodpump', 'advanced', 'final', null, 22, 'Omit the balance from an ODUMA-4 design run. What do torqueGroup and torquePct report, and why is the pair the finding?', '["Both come back null, because the design refuses to rate a gearbox it was given no counterweight for and says so in the same way the RP 11L groups say it, which is what a clean refusal looks like.", "torqueGroup comes back 0.000000000 where the real value is 0.261911618, while torquePct one field away comes back null, so two fields in one object disagree about whether an answer exists.", "Both come back zero, which is the module''s documented convention for a quantity it could not compute, so the two fields agree with each other and a reader is at least not misled by any disagreement.", "torqueGroup comes back 0.261911618 because it can be formed from the card alone, and only torquePct comes back null, since the percentage is the one that needs the gearbox rating of 320000 in-lb."]'::jsonb, 1, 'Zero is the no load axis of the RP 11L torque chart, so a missing balance reads as a weightless gearbox, and the module already knows how to say not computed one field away.'),
  ('rodpump', 'advanced', 'final', null, 23, 'A workflow solves the card, balances the unit with a crank offset of 10 deg, and then runs the design. Where does that offset reach the numbers that come back?', '["Only a torque percentage the caller computes from the balance themselves, 134.032962807 percent against the 140.630030060 percent the design reports, since the design reads no offset at all.", "Every load in the design return, because the offset moves the crank angle the card is sampled at and the card is what the loads are read off.", "The balanced moment and the counterbalance effect alike, since balanceUnit forwards the offset to both and those two are the only fields an offset could touch.", "Nowhere, since the design solves its own card internally afterwards, so whatever the separate balance did was overwritten by the design''s own run."]'::jsonb, 0, 'runRodPumpDesign destructures crankOffsetDeg and then references it nowhere, so two gearbox percentages come out of one design with nothing in either return to say which one read the number.'),
  ('rodpump', 'advanced', 'final', null, 24, 'Ten ODUMA-4 outputs come back strictly equal whether a structural unbalance of 600 lb and a crank offset of 10 deg are passed to the design or not. What has that proved, and what has it not?', '["That the two inputs are read and then multiplied by a factor that happens to be zero on this well, which a wider pair of values would show.", "That the design function is broken and should be expected to fail on any input, since an argument it accepts is an argument it must read.", "That neither value reached any of those ten outputs, and nothing at all about whether the answers themselves are right.", "That the balance is insensitive to those two numbers, since a design that does not move on them is a unit that does not move on them."]'::jsonb, 2, 'Both runs can be equally wrong, and the same two numbers move balanceUnit''s counterbalance moment by 11.077174 percent, so the values were not quiet ones.'),
  ('rodpump', 'advanced', 'final', null, 25, 'What does passing the kinematics of a generic 144 in unit alongside a surface motion of stroke 106.687717 in do to an ODUMA-4 design?', '["It raises the timestep warning, because the two strokes imply different Courant limits on the same node grid.", "It lengthens the plunger stroke in proportion to the longer surface stroke of 143.997728 in.", "It is refused, since a linkage whose stroke does not match the supplied surface motion is treated as the same failure as a linkage that cannot close at every crank angle.", "Nothing at all: the plunger stroke comes back 98.526653099789 in, identical to the run without it, and no warning is raised."]'::jsonb, 3, 'kin is unused and unchecked against the input it duplicates, so a caller can describe one pumping unit in one argument and a different one in the next.'),
  ('rodpump', 'advanced', 'final', null, 26, 'The design hands back a torque percentage that never read the offset it was given, and the diagnostic hands back a plunger stroke resting on a damping ratio nobody measured. What separates those two failures?', '["Nothing separates them, since in both cases the return object carries no provenance, and a number a reader cannot audit has to be treated the same way whichever way it went wrong.", "One is an input that went nowhere with nothing saying so, the other an input honoured but unknowable, which walks the stroke read back 1.402208257 in across a sweep.", "The size, since a gearbox percentage wrong by several points is a design decision while a plunger stroke moving by a fraction of an inch sits inside the two percent the oracle gates the stroke to.", "The direction, since an unread input always makes a design look safer than it is while an unmeasured damping ratio can go either way and averages out across a sweep."]'::jsonb, 1, 'A fails-open is a plausible answer with nothing behind it, while the diagnostic''s damping ratio is a declared input: read the same card back from 0.0500 to 0.2000 and the stroke walks with it.'),
  ('rodpump', 'advanced', 'final', null, 27, 'A crew is given a counterbalance target of 19754.454642 lb for a unit running at a crank offset of -30.0 deg. What have they been asked to hang?', '["Too much, because the effect is read a quarter turn from the bottom of the stroke, where the torque factor of 45.129341579 in is at its largest, which overstates anything derived from it.", "The right weight, since a counterbalance effect is only a way of quoting a moment and the moment of 891505.531225 in-lb the engine solved for does know about the offset.", "Too little, because the effect matching where the counterweight moment actually peaks is 25368.233655 lb, so the quoted target is out by -22.129168 percent.", "The weight for a balanced unit, since the engine drives the two torque peaks to equality at every offset and reports whatever effect that equality required."]'::jsonb, 2, 'The counterbalance effect is how a counterbalance is quoted and how it is measured in the field, and at a zero offset the two routes agree exactly at 13508.771698 lb, which is what names the offset as the cause.'),
  ('rodpump', 'advanced', 'final', null, 28, 'A design sheet carries a worst section loading of 82.873308 percent. A second engineer says the well is corrosive. What happens to the sheet?', '["The loading is judged against a lower line and passes 100 percent below a service factor of 0.828733084, and the design itself never changed.", "The maximum stress rises, because corrosion enters the modified Goodman line through the grade minimum tensile and a corroded rod is judged as a weaker steel.", "Nothing on the sheet moves, because the factor is applied to the loading after it is computed and a percentage of a percentage leaves the ranking of the three sections alone.", "The taper has to be redesigned, because the spread of 6.583710 percentage points across the three sections widens with the factor and a corrosive well needs a stress balanced string."]'::jsonb, 0, 'Sa is T over 4 plus 0.5625 of the minimum stress, all times the service factor, so the same card and the same stresses read 82.873308 percent at 1.0000 and 118.390441 percent at 0.7000.'),
  ('rodpump', 'advanced', 'final', null, 29, 'Bisection on the ODUMA-4 service factor sweep puts the crossing at 0.828733084. What changes about the design as the factor is walked across it?', '["The worst section moves from the top of the string down to the deepest section, whose minimum stress is negative, and that move is what carries the loading over 100 percent.", "The march is rerun against the tighter line, so the card the stresses come off is not the same card on both sides.", "The minimum stress falls with the factor, which is why the allowable falls faster than the loading rises.", "Nothing at all: the same card, the same maximum stress of 25210.199822 psi and the same minimum stress of 2969.187943 psi stand behind every row."]'::jsonb, 3, 'The crossing is the unity loading read as a fraction, so the number deciding whether this string is legal is an opinion about the fluid rather than a property of the steel.'),
  ('rodpump', 'advanced', 'final', null, 30, 'How many figures of a worst section loading belong on a design sheet, and what has to sit beside them?', '["All of them, since runRodPumpDesign returns 82.873308395930 percent and a standalone recomputation from the same card reproduces it to every figure, which is what says the number is exact.", "Two at most, with the service factor, since the grid alone moves that loading 1.577289838 percentage points on ODUMA-4 at the shipped damping.", "Three, with the node count, since the node count is what the spread is a property of and a reader given the grid can repeat the calculation and get the same digits back.", "One, with the rod grade, since the grade fixes the minimum tensile of 115000 psi and therefore everything about the line the loading is measured against."]'::jsonb, 1, 'Agreement between two routes on one grid is not convergence: the same quantity reads 81.748616046 percent at 60 nodes and 83.325905884 percent at 1920.'),
  ('rodpump', 'advanced', 'final', null, 31, 'Two readings of the fillage arithmetic are on offer: that the effective factor is an accounting mistake, and that the plunger genuinely travels further at a partly filled barrel. Which is defensible?', '["The first alone, because a plunger stroke that is not monotone in fillage is the signature of a march that never settled, and a defensible convention would err one way.", "The second alone, because the effective factor sits above the nominal on sixteen rows and below it on three, and an error that changes sign belongs to the well rather than to the arithmetic.", "Both in part, since the plunger really does reach 100.412132 in at a fillage of 0.8200 against 95.508351 in at a full barrel, and what is indefensible is charging the fillage a second time against a volume it already moved.", "Neither, since a produced rate is a swept volume times a fillage by definition, so any gap between the effective and the nominal factor is only the difference between rated and produced."]'::jsonb, 2, 'The overstatement reaches 5.134400 percent at a fillage of 0.8200 and the understatement 2.331398 percent at 0.5500, and a sign that flips inside one sweep is what makes this an accounting question.'),
  ('rodpump', 'advanced', 'final', null, 32, 'The ODUMA-4 round trip propagates 24 harmonics down a card of 186 points whose cap is 92. Which of the two counts in that sentence has this tier been pricing?', '["The 186 points, because that card is already the decimated one and nobody chose it, while the harmonic count is a knob the caller sets.", "The 24 harmonics, since the cap of 92 is the resolution actually on offer and using a quarter of it is what leaves the sum short of the two vertical valve transfers.", "The cap of 92, since a request above it is silently reduced and the engine reports the count it used rather than the count it was asked for.", "Neither, since the round trip agrees with the march to 0.303910 percent and a difference that small sits inside the two percent the oracle gates the plunger stroke to."]'::jsonb, 0, 'predictCard hands out only the decimated card, so the diagnostic reads a subsample nobody asked for, and the harmonic sweep settles into a band from 0.252191287 in at 16 to 0.344508847 in at 91.'),
  ('rodpump', 'advanced', 'final', null, 33, 'Take the diagnostic''s damping ratio on the ODUMA-4 card from 0.0500 to 0.2000. What moves, and what does that cost a reported result?', '["The plunger stroke moves 1.402208257 in across that sweep while the two pump load extremes hold still, so only quantities proportional to the stroke are at risk from the damping.", "The harmonic count actually used rises with the damping ratio, so a higher damping buys a finer reading of the same card and the extremes tighten as it climbs.", "Nothing moves, because the damping enters only as kappa and kappa cancels out of a closed form propagation.", "The minimum pump load goes from -1487.766564 lb to 40.250811 lb, so whether the plunger goes into compression is settled by a number the analyst typed."]'::jsonb, 3, 'Damping is not measurable from a card and the engine refuses only the value 0, so anyone quoting a minimum pump load owes the damping ratio beside it.'),
  ('rodpump', 'advanced', 'final', null, 34, 'Sorting an ODUMA-4 design sheet into measurements, conventions and artefacts, which grouping is right?', '["The reported loads are the measurements, because they come off a card the solver actually marched, while the node count is a convention and the service factor is an artefact of the RP 11BR line.", "The subsample and the node count are artefacts, the service factor and the 0.85 fillage threshold are conventions, and the plunger stroke is as close to a measurement as this engine gets.", "The plunger stroke is a convention because it depends on the assumed fluid load, and the loads are the measurements the march produced.", "Everything the march returns is an artefact, since the march is a discretisation, and only the closed form quantities can be quoted at all."]'::jsonb, 1, 'The plunger stroke moves 0.044644 percent across six node counts while the minimum load moves 10.864298 percent of the smallest, which is what puts them in different piles.'),
  ('rodpump', 'advanced', 'final', null, 35, 'There is no way to call runRodPumpDesign once and get a balanced design. What is the order of work, and why?', '["Run the design first with the structural unbalance and the crank offset passed to it, then balance the surface card it returns, which is the same card the design has already solved internally.", "Balance the unit from the rated capacities of the pumping unit designation, then run the design, since the balance needs no card at all.", "Solve the card, balance it with the structural unbalance and the crank offset passed to the balance, then run the design, which solves the same card again from the same inputs.", "Run the design twice, once with the balance omitted and once with it passed, then take the torqueGroup of 0.261911618 from the second run and the torquePct from the first, since each field is right in one of them."]'::jsonb, 2, 'balanceUnit needs the surface card and runRodPumpDesign calls the card solver internally, so the card is paid for twice, and the two numbers belong to the balance where they are read.'),
  ('rodpump', 'advanced', 'final', null, 36, 'Which refusal in this engine would have caught the kinematics of a generic 144 in unit passed alongside a 106.687717 in surface motion?', '["The speed refusal, since the mismatched geometry changes the surface stroke and therefore the fundamental of 59.134268421585 spm the design is checked against.", "The stroke rating check, which compares the design stroke against the unit stroke and raises strokeOverload whenever the two geometries disagree about how long a stroke is.", "The closure refusal, since a 144 in geometry driven through a 106 in motion is precisely the case where the pitman cannot reach the beam at every crank angle.", "None of them, since every refusal on the list is a parse failure or a physical impossibility, and an argument nothing reads leaves a well formed answer behind it."]'::jsonb, 3, 'That run returns a plunger stroke of 98.526653099789 in, identical to the run without the mismatched kinematics, and no warning at all.'),
  ('rodpump', 'advanced', 'final', null, 37, 'Which single ODUMA-4 rating carries the decimation twice, once directly and once through something solved on top of it?', '["The gearbox percentage, since the card is subsampled and the balance is then solved on that subsample, giving 140.630030060 percent against 144.188481561 percent from the full march.", "The structural percentage, since the peak load is read off the subsample and the capacity of 19800 lb it is divided by was itself chosen from a subsampled peak.", "The stroke percentage, since the surface stroke is taken from the same decimated card the loads are and is then measured against the unit stroke rating.", "None of them, since every rating is a ratio and a ratio of two quantities read off one card carries the sampling in both halves, where it cancels."]'::jsonb, 0, 'balanceUnit takes a card load function and the only surface card predictCard hands out is the 186 point one, so the subsample runs one level deeper here than it does in the structural check.'),
  ('rodpump', 'advanced', 'final', null, 38, 'Three checks in one ODUMA-4 design read a peak load. Which reads which, and what follows?', '["All three read prlPeakLb, since it is the only peak polished rod load the return object actually names, and the tension envelope is used for the section stresses and for nothing that a rating is checked against.", "The modified Goodman line reads the envelope, the structural rating reads prlPeakLb and the gearbox rating reads a torque balanced against the subsample, so one design is checked against two samplings.", "The Goodman line and the structural rating both read the envelope, and only the gearbox check is fed the decimated card.", "Each check reads the sampling it names in the returned object, so a caller comparing a load with a rating can always tell which of the two routes produced the number in front of them and reconcile the pair."]'::jsonb, 1, 'Against a 19800 lb capacity the structural percentage reads 98.716554461 from prlPeakLb and 100.624498834 from the marched peak, so the check deciding whether the unit is big enough is the one reading the smaller number.'),
  ('rodpump', 'advanced', 'final', null, 39, 'Somebody hands you a worst section loading of 88.179235 percent for ODUMA-4. What two numbers do you need beside it before it is reportable?', '["The peak and the minimum polished rod load, since the loading is the ratio between them.", "The cardSamples and the maxCycles the card was solved at, since those two decide how much of the march reached the stress check.", "The service factor it was computed at and the node spread at that speed, which is 0.936333 percentage points at 10.6 spm.", "The structural capacity and the gearbox rating of the unit, since a loading is a percentage of a rating."]'::jsonb, 2, 'At a service factor of 0.8500 the same ODUMA-4 card reads 97.498010 percent and at 0.8000 it reads 103.591635 percent, and the grid moves the same quantity 1.577289838 percentage points at the shipped speed.'),
  ('rodpump', 'advanced', 'final', null, 40, 'Two figures on one design sheet are unsound for opposite reasons: one is exact arithmetic on too coarse a sample, the other arithmetic that never ran. Which can a note rescue?', '["Both, provided the sheet states the card sample count of 180 and the node count of 120, those two being the only settings anywhere in a design a reader cannot otherwise see.", "Neither, because a number a reader cannot audit is unusable however it is annotated, so the repair in both cases is a change to the engine rather than to the sheet.", "The second, since an input that went nowhere is recovered by handing the same two numbers to balanceUnit, while a subsampled load cannot be recovered without rerunning the march.", "The first, since a minimum load of 2625.472706 lb can be labelled as read off 186 points, while a percentage that never read the offset it was handed carries nothing on its face at all."]'::jsonb, 3, 'The reported minimum is 1.247555046 times the marched one and that ratio can be quoted, whereas nothing in a design return says a structural unbalance and a crank offset went nowhere.'),
  ('rodpump', 'advanced', 'final', null, 41, 'One plunger stroke moves 0.043975327 in across six node counts and another moves 1.402208257 in across a damping sweep. What does that pair settle about the two solvers?', '["That the marched stroke is the converged half of its own sweep at 0.044644 percent, while the stroke read back rests on an input nobody measured and moves far further.", "That the diagnostic is the more converged of the two, since a closed form propagation per harmonic carries no time step and no node spacing to be refined at all.", "That the two are one finding stated twice, since a damping ratio and a node count are both solver settings that leave the well itself entirely unchanged.", "That neither stroke may be quoted, since a quantity moving at all under a parameter that changes nothing about the well is the solver''s own noise."]'::jsonb, 0, 'The node sweep moves the marched plunger stroke by 0.044644 percent while the loads move much further, and the stroke read back walks from 100.225350964 in at a damping of 0.0500 to 98.910913848 in at 0.2000.'),
  ('rodpump', 'advanced', 'final', null, 42, 'Which of the two samplings behind an ODUMA-4 reported peak load can a studio user change, and how do their sizes compare?', '["The card samples only, through the design function''s own documented input list, and the subsample is the far larger of the two effects on the peak by something like an order of magnitude.", "The node count only, since the grid is a solver setting a caller may choose while the card length is fixed by the plotting routine, and the grid effect on the peak is negligible beside the subsample.", "Neither, since runRodPumpDesign forwards neither cardSamples nor nodes, and the two are comparable: the subsample costs 1.896103 percent and the grid moves the peak 1.683064 percent.", "Both, through predictCard, which the studio calls, and the subsample is roughly ten times the grid effect on the peak."]'::jsonb, 2, 'Every number a studio user sees was computed on a grid they cannot see and read off a card they cannot lengthen, and the two effects on the peak are of the same order.');
